// Üretilen dosya: tool/ozgun/uret.py. Tarih · Osmanlı Devleti: kuruluştan dağılmaya olaylar, kurumlar, kişiler (orta).
const ozHistory3Orta = <(String, String, List<String>, String)>[
  ('Osmanlı Beyliği\'nin kısa sürede büyümesinde Bizans sınırında bir uç beyliği olarak kurulmasının başlıca etkisi ne olmuştur?', 'Gaza ve cihat anlayışıyla çevreden savaşçı ve göçmen çekmesi', ['Anadolu beylikleriyle sürekli savaş hâlinde bulunup onları yenmesi', 'Moğollardan düzenli askerî yardım alması', 'Deniz ticaretinden büyük gelir sağlaması'], 'Bizans\'a komşu uç bölgesi, gaza düşüncesiyle hareket eden Türkmen savaşçıları ve göçmenleri beyliğe çekmiş; bu da hızlı büyümeyi sağlamıştır.'),
  ('Osman Bey döneminde Bizans tekfurlarıyla yapılan ve Osmanlıların Bizans\'a karşı ilk önemli zaferi sayılan savaş hangisidir?', 'Koyunhisar (Bafeus) Savaşı', ['Maltepe (Pelekanon) Savaşı', 'Sırpsındığı Savaşı', 'Çirmen Savaşı'], '1302\'deki Koyunhisar (Bafeus) Savaşı, Osmanlıların Bizans\'a karşı kazandığı ilk büyük zafer olarak kabul edilir.'),
  ('Kuruluş döneminde ahilerin, abdalların ve gazilerin beyliğe katılması Osmanlı devletine en çok hangi açıdan katkı sağlamıştır?', 'Fethedilen yerlerin Türkleşmesi ve İslamlaşmasına', ['Güçlü bir donanmanın kurulmasına ve uzak deniz seferlerine', 'Matbaanın erken dönemde kullanılmasına', 'Merkezî bürokrasinin Bizans\'tan alınmasına'], 'Bu zümreler fethedilen yerlere yerleşip tekke, zaviye ve esnaf teşkilatları kurarak bölgenin Türk-İslam yurdu hâline gelmesine katkı sağladı.'),
  ('Osman Bey döneminde Osmanlı topraklarının bulunduğu bölge ile ilgili hangisi doğrudur?', 'Söğüt ve Domaniç çevresinde, Bizans sınırında yer alıyordu', ['Ege kıyısında, Ceneviz ticaret kolonilerinin hemen yanında bulunuyordu', 'Doğu Anadolu\'da, İlhanlı sınırında yer alıyordu', 'Karadeniz kıyısında, Trabzon Rum Devleti\'ne komşuydu'], 'Beyliğin çekirdeği Söğüt ve Domaniç yöresiydi; bu bölge Bizans\'ın Bithynia sınırına komşuydu.'),
  ('Orhan Bey\'in Bizans\'a karşı kazandığı ve İznik\'in fethine zemin hazırlayan 1329 tarihli savaş hangisidir?', 'Maltepe (Pelekanon) Savaşı', ['Koyunhisar (Bafeus) Savaşı', 'Sazlıdere Savaşı', 'Kosova Savaşı'], 'Maltepe (Pelekanon) Savaşı\'nda Bizans ordusu yenildi; ardından İznik 1331\'de Osmanlıların eline geçti.'),
  ('Karesi Beyliği\'nin Orhan Bey döneminde Osmanlı topraklarına katılmasının en önemli sonucu hangisidir?', 'Osmanlıların Çanakkale kıyılarına ulaşıp denizcilik birikimi kazanması', ['Osmanlıların ilk kez Doğu Anadolu ve Kafkasya içlerine doğru yayılması', 'Mısır\'la ilk ticaret antlaşmasının imzalanması', 'Başkentin Edirne\'ye taşınması'], 'Karesi\'nin alınmasıyla Osmanlılar Çanakkale Boğazı kıyısına ulaştı ve Karesi denizcileri Rumeli\'ye geçişte önemli rol oynadı.'),
  ('Osmanlıların Rumeli\'de ilk kalıcı toprak parçası olarak 1353\'te ele geçirdiği kale hangisidir?', 'Çimpe Kalesi', ['Gelibolu Kalesi', 'Edirne Kalesi', 'Rumeli Hisarı'], 'Bizans iç savaşında yardım karşılığı Çimpe Kalesi Osmanlılara geçti; Rumeli\'deki ilk üs burası oldu.'),
  ('Osmanlı\'da ilk düzenli ordu birlikleri olan yaya ve müsellemler hangi hükümdar döneminde kurulmuştur?', 'Orhan Bey', ['Osman Bey', 'I. Murad', 'Yıldırım Bayezid'], 'Yaya (piyade) ve müsellem (atlı) birlikleri Orhan Bey döneminde kurulan ilk düzenli askerî birliklerdir.'),
  ('Haçlılarla Osmanlılar arasında yapılan ilk savaş kabul edilen 1364 tarihli savaş hangisidir?', 'Sırpsındığı Savaşı', ['Niğbolu Savaşı', 'Varna Savaşı', 'II. Kosova Savaşı'], 'Sırpsındığı Savaşı (1364), Osmanlılara karşı oluşturulan ilk Haçlı ittifakının yenildiği savaştır.'),
  ('1389\'daki I. Kosova Savaşı\'nın Osmanlı tarihi açısından önemli bir özelliği hangisidir?', 'Savaş alanında şehit düşen ilk Osmanlı hükümdarı I. Murad\'dır', ['Osmanlıların denizde kazandığı ilk büyük zaferdir', 'Osmanlıların Anadolu\'daki Türk beylikleriyle yaptığı ilk büyük savaştır', 'Osmanlıların yenildiği ilk Haçlı savaşıdır'], 'I. Kosova Savaşı kazanıldı ancak I. Murad savaş alanında bir Sırp soylusu tarafından şehit edildi.'),
  ('Yeniçeri Ocağı\'nın kaynağını oluşturan pençik sistemi hangi hükümdar döneminde uygulanmaya başlanmıştır?', 'I. Murad', ['Orhan Bey', 'II. Murad', 'Fatih Sultan Mehmed'], 'Savaş esirlerinin beşte birinin devlete ayrılması anlamına gelen pençik sistemi I. Murad döneminde başlatılmış ve Yeniçeri Ocağı bu esirlerle kurulmuştur.'),
  ('1371 Çirmen Savaşı\'nda Sırp kuvvetlerinin Meriç kıyısında yenilmesi Osmanlılara hangi bölgenin yolunu açmıştır?', 'Makedonya ve Sırbistan\'ın içlerine', ['Anadolu\'daki Karamanoğulları topraklarına', 'Kırım ve Kuzey Karadeniz\'e', 'Ege adalarına ve Rodos\'a'], 'Çirmen zaferiyle Sırp despotlukları Osmanlı\'ya bağlandı ve Makedonya üzerinden Balkanlar\'ın içlerine ilerleme imkânı doğdu.'),
  ('Osmanlı\'da ilk kazasker ve Rumeli beylerbeyiliği hangi dönemde ortaya çıkmıştır?', 'I. Murad dönemi', ['Orhan Bey dönemi', 'Yıldırım Bayezid dönemi', 'II. Murad dönemi'], 'Rumeli\'deki genişleme sonucunda I. Murad döneminde Rumeli beylerbeyiliği ve kazaskerlik makamı oluşturuldu.'),
  ('I. Murad döneminde Rumeli\'de fethedilen yerlere Anadolu\'dan Türkmen nüfusun yerleştirilmesinin temel amacı neydi?', 'Fethedilen bölgelerde Osmanlı hâkimiyetini kalıcı hâle getirmek', ['Anadolu\'daki tarım alanlarını genişletmek ve yeni köyler kurmak için iş gücü sağlamak', 'Bizans\'la ticareti artırmak', 'Rumeli\'de yeni beylikler kurdurmak'], 'İskân politikası, yeni alınan Rumeli topraklarında Türk nüfusu oluşturarak egemenliği kalıcılaştırmayı amaçlıyordu.'),
  ('Niğbolu zaferinin ardından Yıldırım Bayezid\'e Abbasi halifesinden gönderilen unvan hangisidir?', 'Sultan-ı İklim-i Rum', ['Kayser-i Rum', 'Hâdimü\'l-Haremeyn', 'Sultan-ı Selâtin'], 'Niğbolu zaferinden sonra Kahire\'deki Abbasi halifesi Bayezid\'e \'Sultan-ı İklim-i Rum\' unvanını gönderdi.'),
  ('İstanbul\'u kuşatan ilk Osmanlı hükümdarı olan Yıldırım Bayezid\'in Anadolu yakasında yaptırdığı hisar hangisidir?', 'Anadolu Hisarı', ['Rumeli Hisarı', 'Yedikule Hisarı', 'Kilitbahir Kalesi'], 'Anadolu Hisarı (Güzelcehisar), İstanbul kuşatması hazırlığında Yıldırım Bayezid tarafından yaptırıldı.'),
  ('Ankara Savaşı sırasında Kara Tatarların ve beylik askerlerinin Timur tarafına geçmesi, Yıldırım Bayezid\'in hangi politikasına tepki olarak yorumlanır?', 'Anadolu beyliklerini hızla ve zorla Osmanlı\'ya katması', ['Rumeli\'de Anadolu\'dan getirilen nüfusla geniş bir iskân politikası yürütmesi', 'Bizans\'la uzun süreli barış yapması', 'Memlüklerle ittifak kurması'], 'Bayezid Anadolu beyliklerini kısa sürede ilhak etmişti; topraklarını kaybeden beylerin askerleri savaşta Timur\'un yanına geçti.'),
  ('Ankara Savaşı\'nın Bizans açısından sonucu aşağıdakilerden hangisidir?', 'İstanbul\'un düşüşü yaklaşık yarım yüzyıl gecikti', ['Bizans, Balkanlar\'daki kaybettiği tüm topraklarını geri aldı', 'Bizans, Timur\'a bağlı bir eyalet hâline geldi', 'Bizans, Anadolu\'da yeni bir beylik kurdu'], 'Osmanlı\'nın yenilip iç karışıklığa düşmesi Bizans\'a nefes aldırdı; İstanbul ancak 1453\'te fethedilebildi.'),
  ('Yıldırım Bayezid döneminde Osmanlı topraklarına katılan Sivas ve çevresi daha önce hangi Türk devletinin elindeydi?', 'Kadı Burhaneddin Devleti', ['Akkoyunlu Devleti', 'Dulkadiroğulları', 'Ramazanoğulları'], 'Kadı Burhaneddin\'in ölümünden sonra Sivas ve çevresi Yıldırım Bayezid tarafından Osmanlı\'ya bağlandı.'),
  ('Çelebi Mehmed döneminde ortaya çıkan ve dinî-toplumsal nitelikli olarak bilinen isyanın lideri kimdir?', 'Şeyh Bedreddin', ['Kalender Çelebi', 'Baba İshak', 'Şahkulu'], 'Şeyh Bedreddin isyanı Çelebi Mehmed döneminde Rumeli ve Batı Anadolu\'da etkili oldu ve bastırıldı.'),
  ('Çelebi Mehmed\'e \'Osmanlı Devleti\'nin ikinci kurucusu\' denilmesinin nedeni hangisidir?', 'Fetret Devri\'ni bitirip siyasi birliği yeniden sağlaması', ['Osmanlı\'nın ilk başkentini fethetmesi', 'İlk Osmanlı donanmasını kurup Akdeniz\'de ilk deniz seferlerini başlatması', 'Halifeliği Osmanlı\'ya getirmesi'], 'Çelebi Mehmed, kardeşlerini yenerek parçalanmış devleti yeniden birleştirdiği için ikinci kurucu sayılır.'),
  ('1448 II. Kosova Savaşı\'nın en önemli sonucu hangisidir?', 'Balkanlar\'da inisiyatif Osmanlı\'ya geçti ve Haçlılar uzun süre saldırıya cesaret edemedi', ['Osmanlılar ilk kez Rumeli\'ye geçti', 'Bizans İmparatorluğu Osmanlı\'ya bağlandı', 'Osmanlı başkenti Edirne\'den yeniden Bursa\'ya taşındı ve Rumeli\'de geri çekilme başladı'], 'II. Kosova zaferiyle Balkanlar\'da Türk hâkimiyeti kesinleşti ve Haçlıların taarruz gücü kırıldı.'),
  ('II. Murad döneminde Osmanlı topraklarına katılan Anadolu beyliği hangisidir?', 'Germiyanoğulları', ['Karamanoğulları', 'Candaroğulları', 'Dulkadiroğulları'], 'Germiyan Beyi II. Yakup ölünce topraklarını vasiyetle Osmanlı\'ya bıraktı (1429).'),
  ('II. Murad döneminde 1430\'da Venediklilerden alınarak Osmanlı\'ya katılan Ege kıyısındaki önemli liman şehri hangisidir?', 'Selanik', ['Atina', 'Mora', 'Rodos'], 'Selanik 1430\'da II. Murad tarafından Venediklilerden fethedildi.'),
  ('İstanbul kuşatmasında gemilerin karadan yürütülerek Haliç\'e indirilmesinin askerî amacı neydi?', 'Haliç\'i kapatan zinciri etkisiz kılıp surları iki yönden zorlamak', ['Bizans donanmasını Marmara\'ya çekmek', 'Boğaz\'dan geçen ticaret gemilerini korumak', 'Galata\'yı Cenevizlilerden almak'], 'Haliç\'in ağzı zincirle kapalı olduğundan gemiler karadan indirildi; böylece Haliç surları da tehdit altına alındı.'),
  ('İstanbul\'un fethinde kullanılan büyük topları döken usta olarak bilinen kişi kimdir?', 'Macar Urban', ['Ali Kuşçu', 'Mimar Hayreddin', 'Hezarfen Ahmed Çelebi'], 'Macar asıllı top dökümcüsü Urban, kuşatmada kullanılan büyük toplarıyla tanınır.'),
  ('Fethin ardından Fatih\'in Rum Ortodoks Patrikhanesi\'ni koruması ve patriği yeniden seçtirmesi hangi politikasının ürünüdür?', 'Gayrimüslim tebaaya din ve inanç serbestliği tanıma anlayışının', ['Ortodoks tebaayı zamanla Katolik mezhebine geçirme ve Papalığa bağlama amacının', 'Patriği Osmanlı veziri yapma çabasının', 'Rumları İstanbul\'dan sürgün etme planının'], 'Fatih, Gennadios\'u patrik seçtirerek Ortodoks tebaaya dinî özerklik tanıdı; bu hem hoşgörünün hem Katolik-Ortodoks ayrılığını kullanmanın ifadesiydi.'),
  ('Fatih\'in fetihten sonra İstanbul\'a Anadolu ve Rumeli\'den nüfus getirmesinin temel amacı hangisidir?', 'Boşalan şehri yeniden canlandırıp imparatorluk başkenti hâline getirmek', ['Rumeli\'deki tımar sistemini tamamen kaldırıp yerine iltizam uygulamasını getirmek', 'Yeniçeri sayısını azaltmak', 'Bursa\'yı başkent olmaktan çıkarmamak'], 'Kuşatma sonrası nüfusu azalan İstanbul, sürgün ve iskânla yeniden şenlendirilerek başkent yapıldı.'),
  ('Fatih Sultan Mehmed\'in hocası olan ve kuşatma sırasında Eyüp Sultan\'ın kabrinin yerini bulduğu rivayet edilen âlim kimdir?', 'Akşemseddin', ['Molla Gürani', 'Şeyh Edebali', 'Ebussuud Efendi'], 'Akşemseddin Fatih\'in manevi hocasıdır; Eyüp Sultan\'ın kabrinin yerini onun gösterdiği rivayet edilir.'),
  ('Fatih döneminde Amasra\'nın Cenevizlilerden, Trabzon Rum İmparatorluğu\'nun topraklarının da Osmanlı\'ya katılması hangi amaca hizmet etmiştir?', 'Karadeniz\'i Osmanlı denetimine almaya', ['Akdeniz\'de Venedik\'le ittifak kurmaya', 'İran ticaret yolunu Safevilere bırakmaya', 'Balkanlar\'da Macarlarla sınır belirlemeye'], 'Amasra, Sinop, Trabzon ve 1475\'te Kırım\'ın bağlanmasıyla Karadeniz büyük ölçüde bir Osmanlı gölüne dönüştü.'),
  ('1475\'te Fatih döneminde Osmanlı\'ya bağlanan ve uzun süre Osmanlı\'nın kuzeydeki müttefiki olan devlet hangisidir?', 'Kırım Hanlığı', ['Kazan Hanlığı', 'Altın Orda Devleti', 'Astrahan Hanlığı'], 'Kırım Hanlığı 1475\'te Gedik Ahmed Paşa\'nın seferiyle Osmanlı\'ya bağlandı.'),
  ('Fatih Sultan Mehmed\'in yayımladığı Kanunname-i Âl-i Osman\'ın en dikkat çekici yönlerinden biri hangisidir?', 'Devlet teşkilatını düzenlemesi ve kardeş katline hukuki dayanak sağlaması', ['Osmanlı\'da ilk anayasal düzeni kurup meclisi açması', 'Tımar sistemini kaldırıp iltizamı tek yöntem yapması', 'Gayrimüslimlere tam siyasi eşitlik tanıması'], 'Teşkilat kanunnamesi olarak bilinen bu metin, makamları ve törenleri düzenlemiş, kardeş katline de hukuki dayanak sağlamıştır.'),
  ('Fatih döneminde fethedilen ve Bosna\'da İslamlaşma sürecinin hızlanmasında etkili olan Hristiyan mezhebi mensupları hangi adla bilinir?', 'Bogomiller', ['Kalvenistler', 'Nasturiler', 'Monofizitler'], 'Katolik baskısına maruz kalan Bogomiller, Osmanlı fethinden sonra büyük ölçüde İslam\'a geçti.'),
  ('Fatih Sultan Mehmed\'in İstanbul\'da yaptırdığı ve bir külliye etrafında yükseköğretim kurumu niteliği taşıyan medreseler topluluğu hangisidir?', 'Sahn-ı Seman Medreseleri', ['Süleymaniye Külliyesi Medreseleri', 'Darülhadis Medresesi', 'Orhaniye Medresesi'], 'Fatih Külliyesi içindeki sekiz medreseye Sahn-ı Seman denir; dönemin en yüksek öğretim kurumlarıdır.'),
  ('II. Bayezid döneminde İspanya\'dan sürülen Müslüman ve Yahudilerin Osmanlı donanmasıyla taşınması 1492\'de hangi gelişmenin ardından gerçekleşti?', 'Gırnata\'nın (Granada) düşmesi', ['Viyana\'nın Osmanlılarca kuşatılması', 'Rodos\'un fethi', 'Kıbrıs\'ın alınması'], '1492\'de Gırnata\'nın düşmesiyle Endülüs\'teki son Müslüman devlet yıkıldı; Kemal Reis\'in gemileri mültecileri Osmanlı topraklarına taşıdı.'),
  ('II. Bayezid döneminde Kili ve Akkerman\'ın alınmasının stratejik önemi nedir?', 'Karadeniz\'in kuzeybatısının ve Kırım ile kara bağlantısının güvenceye alınması', ['Mısır\'a ve Hicaz\'a giden hac yolunun bütünüyle güvence altına alınıp korunması', 'İran ipek yolunun Osmanlı\'ya geçmesi', 'Venedik\'in Ege\'den tamamen atılması'], 'Kili ve Akkerman, Tuna ağzı ile Dinyester çevresini kontrol eden limanlardı; Kırım\'la kara bağlantısını sağladılar.'),
  ('Anadolu\'da Safevi propagandası etkisiyle II. Bayezid döneminin sonlarında çıkan isyan hangisidir?', 'Şahkulu İsyanı', ['Patrona Halil İsyanı', 'Kabakçı Mustafa İsyanı', 'Celali Karayazıcı İsyanı'], '1511\'deki Şahkulu İsyanı, Safevi yanlısı Türkmenlerin Teke yöresinde başlattığı büyük bir isyandır.'),
  ('II. Bayezid döneminde Osmanlı donanmasının Venedik\'e karşı kazandığı başarılar (İnebahtı, Modon, Koron) neyi göstermektedir?', 'Osmanlı deniz gücünün Akdeniz\'de yükselmeye başladığını', ['Osmanlı\'nın karadaki tüm seferlerini durdurduğunu', 'Venedik\'in Osmanlı\'ya kapitülasyon verdiğini', 'Osmanlı donanmasının yalnız Karadeniz\'de faaliyet gösterdiğini'], '1499-1503 savaşında Mora\'daki Venedik üslerinin alınması Osmanlı deniz gücünün yükselişini gösterir.'),
  ('Mısır seferi sonucunda halifeliğin Osmanlı\'ya geçmesi Osmanlı Devleti\'ne en çok hangi açıdan güç kazandırmıştır?', 'İslam dünyasında dinî ve siyasi liderlik iddiasını güçlendirmiştir', ['Avrupa\'daki Katolik devletlerle kalıcı askerî ittifaklar kurmasını sağlamıştır', 'Kapitülasyonları kaldırmasını mümkün kılmıştır', 'Tımar sistemini sona erdirmiştir'], 'Halifelik, Osmanlı padişahına bütün Müslümanlar üzerinde manevi bir otorite sağlamış ve İslam dünyasının önderliğini pekiştirmiştir.'),
  ('Çaldıran zaferinin Osmanlı açısından ekonomik sonuçlarından biri hangisidir?', 'İpek Yolu ticaretinde Safevi etkisinin zayıflaması', ['Hindistan ile doğrudan deniz ticaretine başlanması', 'Venedik\'in Osmanlı limanlarındaki tüm ticaret ayrıcalıklarının kaldırılması', 'Osmanlı\'nın Atlantik\'e açılması'], 'Çaldıran\'dan sonra Doğu Anadolu ve İpek Yolu\'nun önemli bir kesimi Osmanlı denetimine girdi.'),
  ('Yavuz Sultan Selim\'e Mekke Şerifi tarafından gönderilen ve kutsal şehirlerin hizmetkârı anlamına gelen unvan hangisidir?', 'Hâdimü\'l-Haremeyni\'ş-Şerifeyn', ['Sultan-ı İklim-i Rum', 'Kayser-i Rum', 'Emirü\'l-Müminin el-Muzaffer'], 'Mısır\'ın fethinden sonra Mekke Şerifi kutsal emanetleri ve şehirlerin anahtarlarını göndererek Yavuz\'u bu unvanla andı.'),
  ('Yavuz Selim\'in Mısır\'ı almasıyla Osmanlı\'nın eline geçen kutsal emanetler ve Kahire\'den getirilen âlimler, ustalar İstanbul\'a hangi açıdan katkı sağladı?', 'İstanbul\'un İslam dünyasının merkezi hâline gelmesine', ['İstanbul\'un Avrupa ile yapılan deniz ticaretinden tamamen kopmasına', 'İstanbul\'un başkent olmaktan çıkmasına', 'İstanbul\'da matbaanın hemen kurulmasına'], 'Hilafet ve kutsal emanetlerle birlikte İstanbul, İslam dünyasının siyasi ve dinî merkezi konumuna yükseldi.'),
  ('Mohaç zaferinden sonra Kanuni\'nin Macaristan\'ı doğrudan ilhak etmek yerine Yanoş Zapolya\'yı kral yapması nasıl açıklanabilir?', 'Habsburglara karşı tampon bölge oluşturma politikasıyla', ['Macaristan\'dan vergi alınmasının şeriat gereği yasaklanmış olmasıyla', 'Macar halkının yeniçeri olmasını önleme amacıyla', 'Papa ile yapılan gizli bir antlaşmanın gereğiyle'], 'Osmanlı, Avusturya ile arasında bağlı bir Macar krallığı bırakarak Habsburglara karşı tampon bölge oluşturdu.'),
  ('Kanuni döneminde Safevilere karşı yapılan Irakeyn Seferi\'nde alınan önemli şehir hangisidir?', 'Bağdat', ['Tebriz', 'İsfahan', 'Herat'], '1534\'teki Irakeyn Seferi\'nde Bağdat alındı ve Irak Osmanlı\'ya katıldı.'),
  ('1555 Amasya Antlaşması\'nın Osmanlı-Safevi ilişkileri açısından önemi hangisidir?', 'İki devlet arasında yapılan ilk resmî barış antlaşması olması', ['Safevi Devleti\'nin Osmanlı\'ya katılmasını sağlaması', 'Osmanlı\'nın İran\'ın tamamını ele geçirmesi', 'Halifeliğin Safevilere devredilmesi'], 'Amasya Antlaşması Osmanlı ile Safeviler arasındaki ilk resmî antlaşmadır; Bağdat ve Doğu Anadolu Osmanlı\'da kaldı.'),
  ('Preveze zaferinin Akdeniz siyasetine etkisi aşağıdakilerden hangisidir?', 'Akdeniz\'de uzun süreli Osmanlı deniz üstünlüğünün kurulması', ['Osmanlı\'nın Atlantik ticaretine katılması', 'Venedik\'in Osmanlı\'nın müttefiki olması', 'Osmanlı donanmasının Karadeniz\'e kapanıp Akdeniz\'den çekilmek zorunda kalması'], 'Preveze\'den sonra Akdeniz, İnebahtı\'ya kadar Osmanlı üstünlüğünde kaldı.'),
  ('Hint Okyanusu seferinden sonra karadan dönerken yaşadıklarını Mir\'atü\'l-Memâlik adlı eserde anlatan Osmanlı denizcisi kimdir?', 'Seydi Ali Reis', ['Piri Reis', 'Turgut Reis', 'Oruç Reis'], 'Seydi Ali Reis, filosunun fırtınada dağılmasından sonra Hindistan ve Orta Asya üzerinden döndü ve bunu Mir\'atü\'l-Memâlik\'te anlattı.'),
  ('Osmanlı\'nın 16. yüzyılda Hint Okyanusu\'na seferler düzenlemesinin ana nedeni hangisidir?', 'Portekizlilerin Kızıldeniz ve Basra\'daki ticaret yollarını tehdit etmesi', ['Hindistan\'ı tamamen fethetme planı', 'Çin ile ittifak kurma isteği', 'Doğu Afrika\'daki altın madenlerini ve köle pazarlarını ele geçirme amacı'], 'Ümit Burnu\'nu dolaşan Portekizliler baharat ticaretini kendi rotalarına çekmeye çalışınca Osmanlı, Kızıldeniz ve Basra\'dan seferler düzenledi.'),
  ('Barbaros Hayreddin\'in Cezayir\'i Osmanlı\'ya bağlayarak kaptan-ı derya olması devletin hangi stratejik gereksinimini karşılamıştır?', 'Kuzey Afrika\'daki denizci gücünü Osmanlı donanmasına katmak', ['Osmanlı\'nın İran\'a karşı Basra Körfezi\'nden yeni bir cephe açması', 'Doğu Avrupa\'da Lehistan\'ı kuşatmak', 'Hint Okyanusu\'nda Portekiz\'i tümüyle kovmak'], 'Barbaros\'un katılmasıyla Kuzey Afrika denizcilerinin birikimi Osmanlı donanmasına aktarıldı ve Batı Akdeniz\'de Habsburglara karşı güç kazanıldı.'),
  ('Sokullu Mehmed Paşa\'nın Süveyş Kanalı\'nı açma tasarısının temel amacı hangisidir?', 'Akdeniz ile Kızıldeniz\'i birleştirerek Hint Okyanusu\'na kolay ulaşmak', ['Karadeniz ile Hazar Denizi\'ni birleştirip İran ipeğini doğrudan İstanbul\'a taşımak', 'Mısır\'daki tarım alanlarını sulamak', 'Venedik ile ortak bir liman kurmak'], 'Süveyş tasarısı, donanmanın Akdeniz\'den doğrudan Kızıldeniz\'e geçerek Portekiz\'e karşı Hint Okyanusu\'nda etkili olmasını amaçlıyordu.'),
  ('Kanuni döneminde Cezayir\'den başlayıp Kuzey Afrika\'da Osmanlı\'ya bağlanan yerlere hangi ad verilirdi?', 'Garp Ocakları', ['Rumeli Eyaletleri', 'Uç Beylikleri', 'Mukataa Bölgeleri'], 'Cezayir, Tunus ve Trablusgarp\'a Garp Ocakları denirdi; bu bölgeler geniş özerkliğe sahipti.'),
  ('Kıbrıs\'ın fethi Osmanlı\'nın Doğu Akdeniz\'deki konumunu nasıl etkiledi?', 'Anadolu ile Mısır arasındaki deniz yolu güvenli hâle geldi', ['Osmanlı ilk kez Atlantik\'e açılma imkânı buldu', 'Kızıldeniz\'e geçiş tamamen kapandı', 'Venedik, Osmanlı\'nın ana müttefiki oldu ve ortak donanma kurdu'], 'Kıbrıs, korsanlık üssü olarak İstanbul-İskenderiye deniz yolunu tehdit ediyordu; fetihle bu yol güvenceye alındı.'),
  ('İnebahtı\'dan sonra Venedik elçisine \'Biz Kıbrıs\'ı alarak sizin kolunuzu kestik, siz donanmamızı yakarak sakalımızı tıraş ettiniz\' dediği rivayet edilen sadrazam kimdir?', 'Sokullu Mehmed Paşa', ['Lala Mustafa Paşa', 'Kuyucu Murad Paşa', 'Nevşehirli İbrahim Paşa'], 'Bu söz, kaybedilen donanmanın yeniden yapılabileceğini anlatmak için Sokullu Mehmed Paşa\'ya atfedilir.'),
  ('Sokullu Mehmed Paşa\'nın 1579\'da öldürülmesinden sonra gelişen sürece ilişkin hangi yorum yaygındır?', 'Saray çevresinin ve nüfuz gruplarının etkisinin arttığı', ['Osmanlı\'nın tüm sınırlarında uzun ve kesintisiz bir barış dönemine girdiği', 'Yeniçeri Ocağı\'nın hemen kaldırıldığı', 'Sadrazamlık makamının ortadan kaldırıldığı'], 'Sokullu\'dan sonra sadrazamların sık değişmesi ve saray kliklerinin güçlenmesi, yönetimde istikrarsızlığın göstergesi sayılır.'),
  ('Celali isyanlarının çıkmasında aşağıdakilerden hangisi etkili olmamıştır?', 'Matbaanın yaygınlaşmasıyla muhalif yayınların artması', ['Ağır vergiler ve tımar düzeninin bozulması', 'Uzun savaşlar ve askerden kaçanların çoğalması', 'Nüfus artışı karşısında işlenebilir toprağın yetersiz kalması'], 'Celali isyanlarında vergi yükü, tımar düzeninin bozulması, uzun savaşlar ve nüfus baskısı etkiliydi; matbaanın bu dönemde Osmanlı\'da yaygınlığı yoktu.'),
  ('I. Ahmed döneminde Celali isyanlarını sert yöntemlerle bastırmasıyla tanınan sadrazam kimdir?', 'Kuyucu Murad Paşa', ['Tarhuncu Ahmed Paşa', 'Sokullu Mehmed Paşa', 'Alemdar Mustafa Paşa'], 'Kuyucu Murad Paşa 1607-1609 yıllarında Celali gruplarını büyük ölçüde dağıttı.'),
  ('II. Osman\'ın öldürülmesine yol açan 1622 ayaklanması hangi adla anılır?', 'Haile-i Osmaniye', ['Vaka-i Hayriye', 'Vaka-i Vakvakiye', 'Çınar Vakası'], 'II. Osman yeniçeriler tarafından öldürüldü; Osmanlı tarihinde bir padişahın isyancılarca öldürüldüğü ilk olaydır.'),
  ('II. Osman\'ın tahttan indirilmesinde etkili olan gelişme hangisidir?', 'Ocağı kaldırıp yeni bir ordu kurmayı tasarladığı haberinin yayılması', ['Halifeliği İran\'a devretmek istemesi', 'Başkenti Bursa\'ya taşıma kararını uygulaması', 'Avrupa\'dan getirttiği paralı askerlerle İstanbul\'u işgal ettirip yeniçerileri dağıtması'], 'Hotin Seferi\'nden sonra yeniçerileri cezalandırmak ve yeni bir ordu kurmak istediği söylentisi isyanı başlattı.'),
  ('IV. Mehmed döneminde 1656\'da sarayın önündeki bir çınar ağacına devlet adamlarının asıldığı olaya ne ad verilir?', 'Vaka-i Vakvakiye', ['Haile-i Osmaniye', 'Edirne Vakası', 'Kabakçı Mustafa İsyanı'], 'Çınar Vakası olarak da bilinen Vaka-i Vakvakiye\'de isyancılar saray görevlilerini Sultanahmet\'teki çınara astı.'),
  ('1639\'da Safevilerle imzalanan ve bugünkü Türkiye-İran sınırının büyük ölçüde temelini oluşturan antlaşma hangisidir?', 'Kasr-ı Şirin Antlaşması', ['Amasya Antlaşması', 'Nasuh Paşa Antlaşması', 'Serav Antlaşması'], 'IV. Murad\'ın Bağdat Seferi\'nden sonra imzalanan Kasr-ı Şirin Antlaşması, sınırı büyük ölçüde belirledi.'),
  ('IV. Murad\'ın içki, tütün ve kahvehaneleri yasaklaması ve ağır cezalarla düzen sağlamaya çalışması hangi tür ıslahat anlayışını yansıtır?', 'Baskı ve sertlik yoluyla eski düzeni yeniden kurmayı amaçlayan anlayışı', ['Batı\'yı örnek alıp yeni kurumlar açan, köklü bir yenileşme anlayışını', 'Halka anayasal haklar tanımaya yönelik bir anlayışı', 'Yönetimi yerel ayanlara devretmeyi öngören anlayışı'], '17. yüzyıl ıslahatları genellikle bozulan düzeni sert önlemlerle eski hâline getirmeyi amaçlıyordu; Batı\'yı örnek almıyordu.'),
  ('IV. Murad\'a padişahlık bozukluklarının nedenlerini ve çözüm önerilerini anlatan ünlü risaleyi sunan devlet adamı kimdir?', 'Koçi Bey', ['Kâtip Çelebi', 'Naima', 'Evliya Çelebi'], 'Koçi Bey Risalesi, devletin gerileme sebeplerini ve eski düzene dönüş önerilerini anlatır.'),
  ('1656\'da sadrazam olurken geniş yetkiler isteyen ve Köprülüler dönemini başlatan devlet adamı kimdir?', 'Köprülü Mehmed Paşa', ['Köprülü Fazıl Ahmed Paşa', 'Fazıl Mustafa Paşa', 'Amcazade Hüseyin Paşa'], 'Köprülü Mehmed Paşa, işlerine karışılmaması koşuluyla sadarete geldi ve isyanları sert biçimde bastırdı.'),
  ('II. Viyana bozgunundan sonra Osmanlı\'ya karşı Avusturya, Lehistan, Venedik ve sonradan Rusya\'nın katıldığı ittifaka ne ad verilir?', 'Kutsal İttifak', ['Üçlü İtilaf', 'Viyana Kongresi', 'Mukaddes Roma Birliği'], '1684\'te Papa\'nın öncülüğünde kurulan Kutsal İttifak (Mukaddes İttifak), Osmanlı\'ya karşı uzun bir savaş başlattı.'),
  ('1700 İstanbul Antlaşması\'yla Rusya\'ya bırakılan ve Rusya\'nın Azak Denizi\'ne çıkmasını sağlayan kale hangisidir?', 'Azak Kalesi', ['Özi Kalesi', 'Hotin Kalesi', 'Kerç Kalesi'], '1700 İstanbul Antlaşması\'yla Azak Kalesi Rusya\'ya bırakıldı; Rusya İstanbul\'da daimî elçi bulundurma hakkı da aldı.'),
  ('Prut Antlaşması\'nın Osmanlı için daha kazançlı yapılabileceği yorumunun gerekçesi hangisidir?', 'Kuşatılan Rus ordusu karşısında Azak\'la yetinilmesi', ['Osmanlı\'nın bu antlaşmayla Kırım\'ı kaybetmesi', 'Antlaşmanın Osmanlı\'ya ağır bir savaş tazminatı ve yıllık vergi yükümlülüğü getirmesi', 'Antlaşmayla Rusya\'ya kapitülasyon verilmesi'], 'Rus ordusu teslim olmaya yakınken Azak\'ın iadesi ve birkaç koşulla yetinilmesi, fırsatın değerlendirilmediği şeklinde eleştirilir.'),
  ('Poltava\'da Ruslara yenildikten sonra Osmanlı\'ya sığınan ve Prut Savaşı\'nın arka planında yer alan İsveç kralı kimdir?', 'XII. Şarl', ['II. Gustav Adolf', 'XI. Şarl', 'I. Kristina'], 'İsveç Kralı XII. Şarl (Demirbaş Şarl) Poltava yenilgisinden sonra Osmanlı topraklarına sığındı.'),
  ('1718\'de Avusturya ve Venedik ile imzalanan ve Belgrad\'ın kaybedildiği antlaşma hangisidir?', 'Pasarofça Antlaşması', ['Karlofça (Sremski Karlovci) Antlaşması', 'Belgrad Antlaşması', 'Ziştovi Antlaşması'], 'Pasarofça Antlaşması\'yla Belgrad Avusturya\'ya bırakıldı; Mora ise Venedik\'ten geri alınmıştı.'),
  ('Pasarofça Antlaşması\'nın ardından Osmanlı\'da başlayan döneme ilişkin hangisi doğrudur?', 'Batı\'nın üstünlüğü kabul edilip ilk kez Batı örnek alınmıştır', ['Osmanlı, Avrupa\'ya karşı yeni bir büyük fetih dönemine girmiştir', 'Tımar sistemi yeniden güçlendirilerek eski düzen kurulmuştur', 'Osmanlı, bütün Avrupa devletleriyle diplomatik ilişkiyi kesmiştir'], 'Pasarofça\'dan sonraki Lale Devri\'nde ilk kez Batı örnek alınarak kültürel ve teknik yenilikler yapıldı.'),
  ('İbrahim Müteferrika matbaasıyla ilgili hangisi doğrudur?', 'Dinî eserler dışında sözlük, tarih ve coğrafya kitapları basılmıştır', ['Kurulduğu ilk yıl Kur\'an-ı Kerim basılmıştır', 'Yalnız Fransızca eserler basmak için kurulmuştur', 'İlk basılan eser Kanun-i Esasi\'dir'], 'Şeyhülislam fetvasıyla dinî eserler kapsam dışında tutuldu; ilk eser Vankulu Lügati\'dir.'),
  ('İbrahim Müteferrika matbaasında basılan ilk kitap hangisidir?', 'Vankulu Lügati', ['Cihannüma', 'Takvim-i Vekayi', 'Kitab-ı Bahriye'], 'İlk basılan eser, Arapçadan Türkçeye çevrilmiş bir sözlük olan Vankulu Lügati\'dir (1729).'),
  ('1739\'da Fransa\'nın arabuluculuğuyla imzalanan ve Belgrad\'ın Osmanlı\'ya geri verildiği antlaşma hangisidir?', 'Belgrad Antlaşması', ['Pasarofça Antlaşması', 'Ziştovi Antlaşması', 'Yaş Antlaşması'], '1739 Belgrad Antlaşması\'yla Belgrad Osmanlı\'ya geri döndü.'),
  ('Küçük Kaynarca Antlaşması\'nda Osmanlı padişahının Kırım Müslümanlarının dinî lideri sayılması neyi göstermektedir?', 'Halifelik makamının ilk kez siyasi bir araç olarak kullanıldığını', ['Kırım\'ın yeniden Osmanlı\'ya tam olarak bağlanıp eyalet hâline getirildiğini', 'Rusya\'nın halifeliği tanımadığını', 'Kırım halkının Hristiyanlığa geçtiğini'], 'Siyasi bağı kopan Kırım üzerinde halifelik sıfatıyla manevi bağ korunmak istendi; halifelik ilk kez dış politikada araç oldu.'),
  ('Küçük Kaynarca Antlaşması\'yla Osmanlı Devleti ilk kez hangi yükümlülüğü kabul etmiştir?', 'Savaş tazminatı ödemeyi', ['Kapitülasyonlar vermeyi kabul etmeyi', 'Elçi göndermeyi', 'Donanma kurmayı'], 'Küçük Kaynarca, Osmanlı\'nın ilk kez savaş tazminatı ödediği antlaşmadır.'),
  ('1791\'de Avusturya ile imzalanan ve Avusturya\'nın Fransız İhtilali nedeniyle savaştan çekilmesiyle sonuçlanan antlaşma hangisidir?', 'Ziştovi Antlaşması', ['Yaş Antlaşması', 'Pasarofça Antlaşması', 'Belgrad Antlaşması'], 'Ziştovi Antlaşması\'yla Avusturya aldığı yerleri büyük ölçüde geri verdi; bu, Osmanlı\'nın Avusturya ile yaptığı son savaştır.'),
  ('III. Selim\'in ıslahatlarına başlamadan önce devlet adamlarından rapor (layiha) istemesi, onun yönetim anlayışı hakkında neyi gösterir?', 'Islahatları danışma ve görüş toplama yoluyla planlama çabasını', ['Ulemayı ve kadıları yönetimden tamamen dışlayıp etkisizleştirme isteğini', 'Yeniçeri Ocağı\'nı hemen kaldırma kararını', 'Meclis kurarak saltanatı sınırlama isteğini'], 'III. Selim, ıslahat öncesinde devlet adamlarından layihalar alarak sorunların ve çözüm yollarının tespitine çalıştı.'),
  ('Nizam-ı Cedid ordusunun masraflarını karşılamak amacıyla oluşturulan hazineye ne ad verilir?', 'İrad-ı Cedid Hazinesi', ['Enderun Hazinesi', 'Darphane Hazinesi', 'Defterdarlık Hazinesi'], 'İrad-ı Cedid, yeni vergiler ve gelirlerle oluşturulan, Nizam-ı Cedid\'i finanse eden ayrı bir hazinedir.'),
  ('III. Selim döneminde Londra, Paris, Viyana ve Berlin\'de daimî elçilikler açılmasının amacı ile en uyumlu ifade hangisidir?', 'Avrupa siyasetini yakından izleyip diplomatik yalnızlıktan kurtulmak', ['Avrupa\'daki Osmanlı topraklarını satmak', 'Avrupa\'dan asker toplamak', 'Hristiyan tebaayı Avrupa\'ya göç ettirmek ve yerlerine Müslüman nüfus yerleştirmek'], 'Daimî elçilikler Avrupa\'daki gelişmeleri takip etmeyi, diplomasiyi kurumsallaştırmayı ve Batı dillerini bilen memur yetiştirmeyi sağladı.'),
  ('Napolyon\'un Mısır seferi, Osmanlı\'nın geleneksel dış politikasında hangi değişime yol açmıştır?', 'Osmanlı\'nın tarihî rakibi Rusya ile ittifak yapmasına', ['Osmanlı\'nın Fransa ile kalıcı ittifakına', 'Osmanlı\'nın Avrupa devletleriyle bütün diplomatik ilişkileri kesmesine', 'Osmanlı\'nın İran ile birleşmesine'], 'Uzun süreli dost Fransa\'nın saldırısı üzerine Osmanlı, Rusya ve İngiltere ile ittifak yaptı; bu dış politikada önemli bir kırılmaydı.'),
  ('Napolyon\'un Akka önlerinde durdurulmasında rol oynayan Osmanlı valisi kimdir?', 'Cezzar Ahmed Paşa', ['Kavalalı Mehmed Ali Paşa', 'Tepedelenli Ali Paşa', 'Alemdar Mustafa Paşa'], 'Akka kalesini savunan Cezzar Ahmed Paşa, İngiliz desteğiyle Napolyon\'un ilerleyişini durdurdu.'),
  ('II. Mahmud\'un divan teşkilatı yerine nazırlıkları (bakanlıkları) kurması hangi değişimi ifade eder?', 'Klasik yönetimden modern bakanlık sistemine geçişi', ['Padişahlığın kaldırılıp cumhuriyete geçilmesini', 'Ulemanın yönetimde tek söz sahibi olmasını', 'Taşra yönetiminin tamamen ayanlara ve derebeylere bırakılmasını'], 'Hariciye, Dahiliye gibi nezaretlerin kurulmasıyla Avrupa tarzı bakanlık sistemine geçildi.'),
  ('II. Mahmud döneminde açılan ve askerî hekim yetiştiren okul hangisidir?', 'Mekteb-i Tıbbiye', ['Mekteb-i Harbiye', 'Mühendishane-i Bahri Hümayun', 'Mekteb-i Mülkiye'], 'Mekteb-i Tıbbiye-i Adliye-i Şahane, 1827\'de askerî hekim yetiştirmek için açıldı.'),
  ('Yunan isyanının çıkmasında Rusya\'nın Odessa\'da kurulmasına izin verdiği Etnik-i Eterya cemiyetinin rolü hangisidir?', 'İsyanı örgütleyip Yunan milliyetçiliğini yaymak', ['Osmanlı\'ya Yunanistan\'ı korumada yardım etmek', 'Yunanlıları Rusya\'ya göç ettirmeye çalışmak', 'Osmanlı ile Rusya arasında arabuluculuk yapmak'], 'Etnik-i Eterya, Yunan bağımsızlığı için gizli örgütlenme ve isyan hazırlığı yapan bir cemiyetti.'),
  ('1829\'da Rusya ile imzalanan ve Yunanistan\'a özerklik verilmesini öngören antlaşma hangisidir?', 'Edirne Antlaşması', ['Hünkâr İskelesi Antlaşması', 'Bükreş Antlaşması', 'Paris Antlaşması'], '1828-1829 Osmanlı-Rus savaşı sonunda Edirne Antlaşması imzalandı; Yunanistan\'a özerklik tanındı.'),
  ('Kavalalı Mehmed Ali Paşa\'nın Osmanlı\'ya isyan etmesinin başlıca nedeni hangisidir?', 'Yardımına karşılık istediği Suriye\'nin verilmemesi', ['Mısır\'da Fransız egemenliğinin kurulması', 'İstanbul\'da Yeniçeri Ocağı\'nın yeniden açılıp Mısır\'a asker gönderilmesi', 'Mısır\'ın Rusya\'ya bırakılması'], 'Yardımları karşılığı Mora ve Girit\'in yanı sıra Suriye valiliğini isteyen Mehmed Ali, bu talebi karşılanmayınca isyan etti.'),
  ('Mısır ordusunun 1832\'de Osmanlı ordusunu yenerek Kütahya\'ya kadar ilerlemesine yol açan savaş hangisidir?', 'Konya Savaşı', ['Nizip Savaşı', 'Ankara Savaşı', 'Kozluca Savaşı'], '1832 Konya Savaşı\'nda Osmanlı ordusu yenildi ve sadrazam esir düştü.'),
  ('1833\'te Osmanlı ile Rusya arasında imzalanan ve Boğazlar konusunda Rusya\'ya ayrıcalık tanıyan antlaşma hangisidir?', 'Hünkâr İskelesi Antlaşması', ['Londra Boğazlar Sözleşmesi', 'Kütahya Antlaşması', 'Edirne Antlaşması'], 'Hünkâr İskelesi\'nde Osmanlı, Rusya\'ya karşı bir savaş durumunda Boğazları Rusya\'nın düşmanlarına kapatmayı kabul etti.'),
  ('1840 Londra Antlaşması\'yla Mehmed Ali Paşa sorunu nasıl çözülmüştür?', 'Mısır valiliği ailesine verildi, Suriye Osmanlı\'ya bırakıldı', ['Mısır tamamen bağımsız bir krallık hâline getirildi ve Sudan\'ı da aldı', 'Mehmed Ali Paşa idam edilerek valilik kaldırıldı', 'Mısır, İngiltere\'nin sömürgesi ilan edildi'], 'Avrupa devletlerinin baskısıyla Mehmed Ali Suriye\'den çekildi; karşılığında Mısır valiliği ailesine verildi.'),
  ('1841 Londra Boğazlar Sözleşmesi\'nin getirdiği temel düzenleme hangisidir?', 'Barışta Boğazların bütün yabancı savaş gemilerine kapalı olması', ['Boğazların barışta ve savaşta yalnız Rus savaş gemilerine açık tutulması', 'Boğazların uluslararası bir komisyona devredilmesi', 'Boğazların ticaret gemilerine kapatılması'], 'Sözleşmeyle Osmanlı barış hâlindeyken Boğazlar tüm yabancı savaş gemilerine kapatıldı; Boğazlar sorunu uluslararası bir mesele oldu.'),
  ('1838 Balta Limanı Ticaret Antlaşması\'nın Osmanlı ekonomisine en önemli olumsuz etkisi hangisidir?', 'Yerli üretici ve esnafın ucuz Avrupa malları karşısında zayıflaması', ['Osmanlı\'nın ilk kez dış borç alması', 'Osmanlı\'nın tüm limanlarını Avrupa gemilerine kapatıp ticareti durdurması', 'Osmanlı parasının basımının durması'], 'Tekel ve iç gümrükler İngiliz tüccarı için kaldırıldı; ucuz İngiliz malları yerli üretimi çökertti.'),
  ('Osmanlı\'nın ilk kapitülasyonlarını verdiği devletlerden biri olarak bilinen, 14. yüzyılda Orhan Bey döneminde ayrıcalık tanınan İtalyan şehir devleti hangisidir?', 'Ceneviz', ['Floransa', 'Napoli', 'Milano'], 'Orhan Bey döneminde 1352\'de Cenevizlilere ticari ayrıcalıklar tanındığı kabul edilir.'),
  ('Kapitülasyonlarla yabancılara tanınan ve Osmanlı yargı egemenliğini zedeleyen ayrıcalık hangisidir?', 'Kendi konsoloslarınca yargılanabilme hakkı', ['Osmanlı ordusunda sınav olmaksızın subay olabilme hakkı', 'Divan-ı Hümayun\'a üye olma hakkı', 'Osmanlı adına para basma hakkı'], 'Yabancılar Osmanlı mahkemeleri yerine kendi konsoloslukları önünde yargılanabiliyordu; bu yargı egemenliğini sınırlıyordu.'),
  ('Tanzimat Fermanı\'ndan kısa süre sonra, 1840\'ta çıkarılan ilk ceza düzenlemesi hangi ad taşır?', 'Ceza Kanunnamesi', ['Mecelle', 'Arazi Kanunnamesi', 'Kanun-i Esasi'], '1840 Ceza Kanunnamesi, Tanzimat\'ın ilanından kısa süre sonra çıkarılan ilk ceza düzenlemesidir; ardından 1858\'de Fransız ceza kanunundan uyarlanan yeni bir kanun geldi.'),
  ('Tanzimat döneminde şer\'i mahkemelerin yanı sıra nizamiye mahkemelerinin kurulması hukukta hangi durumu doğurmuştur?', 'Hukuk ve yargıda ikiliğin ortaya çıkmasını', ['Kadılık kurumunun tamamen kaldırılmasını', 'Şer\'i hukukun tek kaynak olmasını', 'Yargının padişaha bağlanmasını'], 'Batı tarzı nizamiye mahkemeleri ile şer\'i mahkemelerin birlikte varlığı, hukuk ve yargıda ikiliğe yol açtı.'),
  ('1858 Arazi Kanunnamesi\'nin temel amaçlarından biri hangisidir?', 'Toprak mülkiyetini düzenleyip tapu sistemini güçlendirmek', ['Tüm toprakları vakıflara devretmek', 'Tımar sistemini yeniden kurmak', 'Toprakları yalnız yabancılara satmak'], 'Arazi Kanunnamesi miri toprak üzerindeki kullanım haklarını düzenledi; tapu ile özel mülkiyete giden süreci hızlandırdı.'),
  ('Kırım Savaşı sırasında Osmanlı\'nın 1854\'te ilk kez dış borç alması hangi gelişmeye zemin hazırlamıştır?', 'Borçların ödenemez hâle gelmesiyle Düyun-u Umumiye\'nin kurulmasına', ['Kapitülasyonların hemen kaldırılmasına', 'Osmanlı\'nın Avrupa\'ya borç verir duruma gelmesine', 'Osmanlı parasının altına bağlanıp güçlenmesine'], 'Sürekli artan borçlar 1875\'te ödenemez duruma geldi; 1881\'de Düyun-u Umumiye İdaresi kuruldu.'),
  ('Paris Antlaşması\'yla Osmanlı Devleti hangi siyasi topluluğun üyesi kabul edilmiştir?', 'Avrupa Devletler Topluluğu', ['Kutsal İttifak', 'Üçlü İttifak', 'Milletler Cemiyeti ve Uluslararası Divan'], 'Paris Antlaşması\'yla Osmanlı Avrupa devletler topluluğuna dahil edildi ve toprak bütünlüğü Avrupa\'nın güvencesine alındı.'),
  ('Bir Rum tüccarı 1860 yılında İstanbul\'da yeni bir kilise onarmak ve çocukları için okul açmak istiyor. Bu isteklerinin yasal dayanağını en doğrudan hangi belge oluşturur?', 'Islahat Fermanı', ['Sened-i İttifak', 'Kanunname-i Âl-i Osman', 'Hünkâr İskelesi Antlaşması'], '1856 Islahat Fermanı gayrimüslimlere ibadet yerlerini onarma ve okul açma serbestliği tanıdı.'),
  ('1865\'te kurulan ve meşrutiyet ile anayasal yönetimi savunan aydın grubu hangi adla bilinir?', 'Yeni Osmanlılar (Genç Osmanlılar)', ['İttihat ve Terakki Cemiyeti (Selanik)', 'Hürriyet ve İtilaf Fırkası', 'Türk Ocakları'], 'Namık Kemal, Ziya Paşa ve Ali Suavi gibi isimlerin bulunduğu Yeni Osmanlılar meşrutiyet için mücadele etti.'),
  ('Yeni Osmanlıların savunduğu Osmanlıcılık fikrinin temel varsayımı hangisidir?', 'Tüm tebaanın din ve köken farkı gözetmeksizin ortak kimlikte birleşebileceği', ['Yalnız Türklerin devletin asli unsuru olduğu', 'Bütün dünya Müslümanlarının halife etrafında tek bir siyasi birlik içinde toplanması gerektiği', 'Batı uygarlığının tümüyle benimsenmesi gerektiği'], 'Osmanlıcılık, tüm unsurlara eşit haklar tanıyarak ayrılıkçı milliyetçiliği önlemeyi amaçlıyordu.'),
  ('Kanun-i Esasi\'ye göre Meclis-i Mebusan ve Meclis-i Âyan\'dan oluşan meclisin genel adı nedir?', 'Meclis-i Umumi', ['Divan-ı Hümayun', 'Meclis-i Vâlâ', 'Şura-yı Devlet'], 'İki kanatlı meclisin genel adı Meclis-i Umumi idi; âyan üyeleri padişah tarafından atanıyordu.'),
  ('I. Meşrutiyet\'in ilanında İstanbul\'da toplanan Tersane Konferansı\'nın etkisi nasıl yorumlanır?', 'Avrupa\'nın Balkanlara müdahalesini önlemede bir koz olarak kullanıldı', ['Konferansta Osmanlı\'ya yeni topraklar verildi', 'Konferans, ilan edilen anayasayı yürürlükten kaldırmak ve meclisi dağıtmak için toplandı', 'Konferansla Osmanlı Avrupa\'dan tamamen çekildi'], 'Meşrutiyetin konferans sırasında ilanıyla Osmanlı, reformları kendisinin yaptığını göstererek müdahaleyi önlemeye çalıştı.'),
  ('II. Abdülhamid Meclis-i Mebusan\'ı hangi savaşı gerekçe göstererek 1878\'de süresiz tatil etmiştir?', '1877-1878 Osmanlı-Rus Savaşı', ['Kırım Savaşı', 'Trablusgarp Savaşı', '1897 Osmanlı-Yunan (Dömeke) Savaşı'], '93 Harbi\'nin olumsuz gidişatı ve mecliste yükselen eleştiriler üzerine meclis süresiz kapatıldı.'),
  ('I. Meşrutiyet\'in Tanzimat\'tan farklı olarak getirdiği en önemli siyasi yenilik hangisidir?', 'Halkın seçimle yönetime katılmaya başlaması', ['Kanun üstünlüğünün ilk kez bir fermanla kabul edilmesi', 'Gayrimüslimlere eşitlik verilmesi', 'Can ve mal güvenliğinin tanınması'], 'Kanun üstünlüğü ve eşitlik Tanzimat ile başlamıştı; meşrutiyetle ilk kez seçilmiş temsilcilerden oluşan bir meclis kuruldu.'),
  ('93 Harbi\'nde Kafkas cephesinde Gedikler gibi zaferlerle \'Gazi\' unvanını alan Osmanlı kumandanı kimdir?', 'Gazi Ahmed Muhtar Paşa', ['Gazi Osman Paşa', 'Kâzım Karabekir Paşa', 'Enver Paşa'], 'Doğu cephesini yöneten Ahmed Muhtar Paşa, 1877\'deki başarıları üzerine \'Gazi\' unvanını aldı.'),
  ('1878 Ayastefanos Antlaşması\'nın Avrupa devletlerinin tepkisini çekmesinin asıl nedeni neydi?', 'Büyük bir Bulgaristan kurularak Rusya\'nın Balkanlar\'da ve Ege\'de etkin hâle gelmesi', ['Osmanlı\'nın Rusya\'dan büyük toprak kazanması', 'Osmanlı\'nın İngiltere\'ye savaş ilan etmesi', 'Rusya\'nın Kırım\'ı Osmanlı\'ya geri vermesi'], 'Ayastefanos\'la kurulacak büyük Bulgaristan Rusya\'yı sıcak denizlere yaklaştırıyordu; İngiltere ve Avusturya buna karşı çıktı.'),
  ('Berlin Antlaşması\'yla Osmanlı\'nın üç sancağı olan Kars, Ardahan ve Batum\'un Rusya\'ya bırakılması, Türk tarihinde hangi adla anılan sorunun da başlangıcıdır?', 'Elviye-i Selâse meselesi', ['Şark meselesi', 'Boğazlar meselesi', 'Kapitülasyon meselesi'], 'Elviye-i Selâse \'üç sancak\' demektir; bu yerlerin geri alınması uzun süre önemli bir mesele olarak kaldı.'),
  ('93 Harbi\'nden sonra Balkanlar ve Kafkasya\'dan Anadolu\'ya büyük Müslüman göçleri yaşanmıştır. Bu göçlerin Anadolu\'ya demografik etkisi hangisidir?', 'Anadolu\'da Müslüman nüfus oranının artması', ['Anadolu\'nun nüfusunun azalarak boşalması', 'Anadolu\'daki tüm gayrimüslimlerin göç etmesi', 'Göçmenlerin Anadolu yerine Avrupa\'ya yerleştirilmesi'], 'Muhacir akınları Anadolu\'nun Müslüman nüfus oranını artırdı ve şehirlerin sosyal yapısını değiştirdi.'),
  ('Düyun-u Umumiye İdaresi\'nin kurulması Osmanlı egemenliği açısından neden sorunlu kabul edilir?', 'Devletin bazı gelirlerinin yabancıların denetimine geçmesi', ['Osmanlı\'nın tüm toprakları yabancılara satması', 'Osmanlı\'nın yeni borç alamaması', 'Osmanlı ordusunun dağıtılması'], 'Tuz, tütün, ipek gibi gelirlerin toplanması yabancı alacaklıların idaresine bırakıldı; bu mali bağımsızlığı zedeledi.'),
  ('II. Abdülhamid döneminde Doğu Anadolu\'daki aşiretlerden oluşturulan süvari birliklerine ne ad verilir?', 'Hamidiye Alayları', ['Redif Taburları', 'Nizam-ı Cedid Birlikleri', 'Asakir-i Mansure'], 'Hamidiye Alayları 1891\'de kuruldu; bölgede asayişi ve Rus sınırını korumak amaçlanıyordu.'),
  ('II. Abdülhamid döneminde Almanya ile yakınlaşmanın en somut ekonomik göstergesi hangisidir?', 'Bağdat Demiryolu imtiyazının Almanlara verilmesi', ['Kıbrıs\'ın Almanya\'ya bırakılması', 'Almanya\'ya kapitülasyonların kaldırılması', 'Düyun-u Umumiye\'nin Almanya\'ya devredilmesi'], 'Konya\'dan Bağdat\'a uzanacak demiryolu imtiyazı Alman şirketlerine verildi; bu, Almanya\'nın Orta Doğu\'ya açılım politikasının parçasıydı.'),
  ('1897 Osmanlı-Yunan Savaşı\'nın sonuçlarına ilişkin hangisi doğrudur?', 'Savaş kazanıldı ancak büyük devletlerin baskısıyla Girit\'e özerklik verildi', ['Savaş kaybedildi ve Selanik Yunanistan\'a bırakıldı', 'Savaşla Yunanistan Osmanlı\'ya bağlandı', 'Savaş sonunda Girit Osmanlı\'ya tamamen bağlı bir vilayet yapıldı'], 'Dömeke zaferine rağmen Osmanlı toprak kazanamadı; Girit\'e özerklik tanındı.'),
  ('II. Abdülhamid\'in tahta çıkmadan önce, 1876\'da kısa bir süre tahtta kalan ve akıl sağlığı gerekçesiyle tahttan indirilen padişah kimdir?', 'V. Murad', ['Sultan Abdülaziz', 'Sultan Abdülmecid', 'V. Mehmed Reşad'], 'V. Murad yaklaşık üç ay padişahlık yaptı; yerine kardeşi II. Abdülhamid geçti.'),
  ('1876\'da tahttan indirilen ve kısa süre sonra ölü bulunan, Osmanlı donanmasını büyüten padişah kimdir?', 'Sultan Abdülaziz', ['Sultan Abdülmecid', 'II. Mahmud', 'V. Murad'], 'Sultan Abdülaziz 1876\'da Midhat Paşa ve arkadaşlarının darbesiyle tahttan indirildi; onun döneminde güçlü bir zırhlı donanma kurulmuştu.'),
  ('II. Abdülhamid döneminde telgraf hatlarının hızla yaygınlaştırılması yönetim anlayışı açısından nasıl yorumlanabilir?', 'Taşra üzerindeki merkezî denetimi güçlendirme aracı olarak kullanılması', ['Valilere tam bağımsızlık tanınması', 'Haberleşmenin yalnız Avrupa ile sınırlanması', 'Basına tam özgürlük verilmesi'], 'Telgraf, İstanbul\'un taşradan anında bilgi alıp emir göndermesini sağlayarak merkeziyetçi yönetimi güçlendirdi.'),
  ('II. Meşrutiyet\'in ilanında Makedonya\'daki subayların dağa çıkması ve Reval Görüşmesi\'nin yarattığı kaygının etkisi neyi gösterir?', 'Meşrutiyetin daha çok örgütlü subaylarca zorlandığını', ['Meşrutiyetin padişahın kendi isteğiyle hiçbir baskı olmadan ilan edildiğini', 'Meşrutiyetin Avrupa devletlerinin ortak kararıyla ilan edildiğini', 'Meşrutiyetin yalnız İstanbul halkının ayaklanmasıyla ilan edildiğini'], 'İngiliz-Rus yakınlaşmasının Makedonya\'yı Osmanlı\'dan koparacağı korkusu ve İttihatçı subayların eylemi padişahı meşrutiyete zorladı.'),
  ('31 Mart Olayı\'nın ardından II. Abdülhamid\'in tahttan indirilmesinin siyasi sonucu hangisidir?', 'İttihat ve Terakki\'nin yönetimdeki ağırlığının artması', ['Osmanlı\'da saltanatın kaldırılması', 'Meclis-i Mebusan\'ın süresiz kapatılması', 'Kanun-i Esasi\'nin yürürlükten kaldırılması'], 'Hareket Ordusu isyanı bastırdı, II. Abdülhamid tahttan indirildi ve İttihatçıların siyasi etkisi büyük ölçüde arttı.'),
  ('31 Mart Olayı\'nı bastırmak için Selanik\'ten İstanbul\'a gelen askerî kuvvete ne ad verilir?', 'Hareket Ordusu', ['Kuvâ-yı Seyyare', 'Hassa Ordusu', 'Yıldırım Orduları Grubu'], 'Mahmud Şevket Paşa komutasındaki Hareket Ordusu, isyanı bastırdı.'),
  ('Trablusgarp Savaşı\'nı sona erdiren 1912 tarihli antlaşma hangisidir?', 'Uşi (Ouchy) Antlaşması', ['Londra Antlaşması', 'Bükreş Antlaşması', 'İstanbul Antlaşması'], 'Balkan Savaşı\'nın başlaması üzerine Osmanlı, Uşi Antlaşması\'yla Trablusgarp\'ı İtalya\'ya bıraktı.'),
  ('II. Balkan Savaşı\'nın çıkmasının temel nedeni hangisidir?', 'Alınan toprakların paylaşımında anlaşamamaları', ['Osmanlı\'nın kaybettiği toprakları almak için Balkan devletlerine savaş ilan etmesi', 'Rusya\'nın Bulgaristan\'ı işgal etmesi', 'İtalya\'nın Arnavutluk\'u ilhak etmesi'], 'Bulgaristan\'ın aldığı payın büyüklüğüne itiraz eden Sırbistan, Yunanistan ve Romanya Bulgaristan\'a karşı savaştı.'),
  ('Osmanlı\'dan bağımsızlığını 1912\'de ilan eden ve Osmanlı\'nın son ayrılan Balkan unsurlarından olan Müslüman çoğunluklu ülke hangisidir?', 'Arnavutluk', ['Bosna-Hersek', 'Makedonya', 'Karadağ'], 'Arnavutluk 28 Kasım 1912\'de Avlonya\'da bağımsızlığını ilan etti.'),
  ('Çanakkale zaferinin Rusya açısından sonucu hangisidir?', 'Yardım alamaması nedeniyle iç karışıklıklarının hızlanması', ['Rusya\'nın İstanbul\'u ve Boğazları ele geçirerek sıcak denizlere inmesi', 'Rusya\'nın Osmanlı ile ittifak kurması', 'Rusya\'nın Akdeniz\'de üs kurması'], 'Boğazlar açılamadığından Rusya\'ya yardım ulaşmadı; ekonomik çöküş 1917 devrimine giden süreci hızlandırdı.'),
  ('I. Dünya Savaşı\'nda Medine\'yi uzun süre savunarak \'Çöl Kaplanı\' olarak anılan Osmanlı komutanı kimdir?', 'Fahreddin Paşa', ['Cemal Paşa', 'Kâzım Karabekir', 'Halil Kut Paşa'], 'Fahreddin (Türkkan) Paşa, savaş sona erdikten sonra da bir süre Medine\'yi teslim etmedi.'),
  ('Padişah adına yazılan ferman ve beratlara tuğra çeken, ayrıca tapu-tahrir kayıtlarından sorumlu divan üyesi kimdir?', 'Nişancı', ['Defterdar', 'Kadıasker', 'Şeyhülislam'], 'Nişancı, tuğra çekmenin yanı sıra toprak kayıtlarını tutan tahrir defterlerinden de sorumluydu.'),
  ('Divan-ı Hümayun\'da kazaskerlerin görevi düşünüldüğünde bu makamın Osmanlı\'da hangi alanın en üst temsilcisi olduğu söylenebilir?', 'Yargı ve eğitim işlerinin', ['Donanma ve deniz işlerinin', 'Dış ilişkilerin', 'Maliye ve vergilerin'], 'Kazaskerler divanda davalara bakar, kadı ve müderris atamalarında söz sahibi olurdu.'),
  ('Şeyhülislamın Divan-ı Hümayun\'un asıl üyesi olmamasına rağmen fetvalarıyla devlet işlerini etkileyebilmesi neyi gösterir?', 'Kanunların şer\'e uygunluğunda dinî otoritenin önemini', ['Şeyhülislamın sadrazamın ve tüm vezirlerin resmî amiri olduğunu', 'Padişahın yetkisinin bulunmadığını', 'Divanın dinî konuları hiç görüşmediğini'], 'Şeyhülislam, savaş, barış ve kanunların şer\'e uygunluğu hakkında fetva vererek dolaylı ama güçlü bir etki kurardı.'),
  ('Divan-ı Hümayun\'da yazışmaları düzenleyen ve sonradan Hariciye Nazırlığına dönüşen makam hangisidir?', 'Reisülküttaplık', ['Nişancılık', 'Defterdarlık', 'Kubbealtı vezirliği'], 'Reisülküttap, divan kâtiplerinin başıydı; dış yazışmaların artmasıyla önemi büyüdü ve II. Mahmud döneminde Hariciye Nezareti\'ne dönüştü.'),
  ('17. yüzyıldan itibaren devlet işlerinin Divan-ı Hümayun yerine sadrazamın konağında görüşülmeye başlanmasıyla önem kazanan yer hangisidir?', 'Bab-ı Âli', ['Topkapı Sarayı Harem Dairesi', 'Tersane-i Âmire', 'Enderun Mektebi'], 'Paşa Kapısı olarak da bilinen Bab-ı Âli, zamanla hükûmet merkezini simgeler oldu.'),
  ('Klasik dönemde Kubbealtı vezirleri olarak bilinen divan üyeleri ile ilgili hangisi doğrudur?', 'Sadrazama yardım eder, gerektiğinde ordu komuta ederlerdi', ['Yalnız dinî konularda fetva verirlerdi', 'Taşradaki tımarları denetleyen ve vergileri toplayan kadılardı', 'Sarayın Harem bölümünü yönetirlerdi'], 'Kubbealtı vezirleri sadrazama yardım eder, seferlerde serdar olarak ordu komuta edebilirlerdi.'),
  ('Osmanlı\'da sadrazamlık makamının, Fatih\'ten sonra çoğunlukla Enderun\'dan yetişmiş devşirme kökenli kişilere verilmesi hangi amaçla bağlantılıdır?', 'Güçlü ailelerin merkezî iktidara rakip olmasını önlemek', ['Yönetimi Türkmen beylerine teslim etmek', 'Ulemanın devlet yönetimindeki payını artırmak', 'Sadrazamlığı babadan oğula geçirmek'], 'Çandarlı ailesinin tasfiyesinden sonra padişaha bağlı devşirmelere öncelik verilerek güçlü soylu ailelerin oluşması engellendi.'),
  ('İstanbul\'un fethinden sonra Fatih Sultan Mehmed tarafından idam ettirilen ve köklü bir Türk vezir ailesinden gelen sadrazam kimdir?', 'Çandarlı Halil Paşa', ['Zağanos Paşa', 'Mahmud Paşa', 'Karamani Mehmed Paşa'], 'Çandarlı Halil Paşa İstanbul\'un fethinden sonra idam edildi; bundan sonra sadrazamlıkta devşirmeler ağırlık kazandı.'),
  ('Osmanlı sarayında \'Darüssaade Ağası\' (Kızlarağası) ile ilgili aşağıdakilerden hangisi doğrudur?', 'Harem\'in güvenliği ve işleyişinden sorumlu yüksek bir saray görevlisiydi', ['Divan-ı Hümayun\'da maliye işlerine bakardı', 'Yeniçeri Ocağı\'nın komutanıydı', 'Taşrada sancakbeyi olarak görev yapardı'], 'Darüssaade Ağası, Harem\'in yönetiminde ve Haremeyn vakıflarının denetiminde etkili bir saray görevlisiydi.'),
  ('Osmanlı sarayında Enderun\'dan yetişenlerin taşrada sancakbeyi gibi görevlere atanmasına ne ad verilirdi?', 'Çıkma', ['Devşirme', 'Kul kardeşliği', 'Pençik'], 'Saraydan taşraya ya da Birun\'a görevli olarak çıkarılmaya \'çıkma\' denirdi.'),
  ('II. Abdülhamid\'in Dolmabahçe yerine Yıldız Sarayı\'nı tercih etmesi ile ilgili en uygun açıklama hangisidir?', 'Güvenlik kaygısıyla denizden uzak, korunaklı bir yerleşkeyi seçmesi', ['Yıldız Sarayı\'nın Osmanlı\'nın ilk sarayı olması', 'Dolmabahçe Sarayı\'nın yanmış olması', 'Yıldız Sarayı\'nın Edirne\'de bulunması'], 'II. Abdülhamid, darbe ve suikast kaygısıyla tepe üzerindeki Yıldız Sarayı\'nı yönetim merkezi yaptı.'),
  ('Osmanlı\'da kazanın yönetiminde kadının hem yargı hem de belediye işlerine bakması neyi gösterir?', 'Kadının yerel düzeyde yargı ile yönetim işlerini birlikte yürüttüğünü', ['Kazalarda yönetimin tamamen sancakbeyinin askerlerine bırakıldığını', 'Kadıların yalnız miras davalarına baktığını', 'Kazaların merkezden bağımsız olduğunu'], 'Kadı, davalara bakmanın yanında narh, vakıf denetimi, vergi kayıtları ve merkezden gelen emirlerin uygulanmasından da sorumluydu.'),
  ('Mısır, Bağdat ve Habeş gibi eyaletlerin \'salyaneli eyalet\' olarak adlandırılmasının nedeni hangisidir?', 'Tımar uygulanmayıp vergilerin yıllık olarak toplanması', ['Bu eyaletlerin hiçbir vergi ödememesi', 'Yönetimin babadan oğula geçen yerli beylere ve hanedanlara bırakılması', 'Bu eyaletlerin yalnız asker göndermesi'], 'Salyaneli eyaletlerde tımar sistemi uygulanmaz; toplanan vergiden yöneticilerin maaşı ödenir, kalanı İstanbul\'a gönderilirdi.'),
  ('Kutsal şehirler Mekke ve Medine\'nin yönetimi Osmanlı\'da hangi yerel yöneticiye bırakılmıştı?', 'Şerif (Mekke Emiri)', ['Hidiv (Mısır valisi)', 'Bey', 'Dey'], 'Hicaz\'da yönetim Peygamber soyundan gelen şeriflerde kalmış; Osmanlı onlara özel bir statü tanımıştı.'),
  ('Osmanlı\'da sancak düzeyinde güvenlik ve asayişten sorumlu olan, kale ve şehirde kolluk işlerine bakan görevli kimdir?', 'Subaşı', ['Muhtesip', 'Kethüda', 'Mütevelli'], 'Subaşı, sancakbeyinin emrinde şehir ve kasabalarda asayişten sorumlu askerî görevliydi.'),
  ('Osmanlı şehirlerinde çarşı ve pazarları denetleyen, ölçü-tartı hilelerini ve fiyatları kontrol eden görevli kimdir?', 'Muhtesip', ['Subaşı', 'Yasakçı ağası', 'Naib'], 'Muhtesip (ihtisap ağası), kadının yetkisi altında esnafı ve pazarı denetlerdi.'),
  ('Tımar sahibinin, gelirinin belirli bir kısmı karşılığında savaşa getirmek üzere beslediği atlı askerlere ne ad verilirdi?', 'Cebelü', ['Azap', 'Yeniçeri', 'Akıncı'], 'Tımarlı sipahi, gelirinin her 3.000 akçelik fazlası için bir cebelü (atlı asker) yetiştirip sefere götürmekle yükümlüydü.'),
  ('17. yüzyıldan itibaren tımar sisteminin bozulmasının ordu yapısına etkisi hangisidir?', 'Tımarlı sipahi sayısının azalıp maaşlı askerlere duyulan ihtiyacın artması', ['Yeniçeri sayısının azalıp tımarlı sipahinin yeniden ordunun ana gücü olması', 'Donanmanın tamamen dağıtılması', 'Ordunun yalnız gönüllülerden oluşması'], 'Ateşli silahların öne çıkması ve tımarların bozulması sonucu sipahiler geriledi; maaşlı kapıkulu askerine olan ihtiyaç ve hazine yükü arttı.'),
  ('Tımar topraklarının ve vergi kaynaklarının kaydedildiği, belirli aralıklarla yapılan sayımlara ne ad verilir?', 'Tahrir', ['İltizam', 'Müsadere', 'Narh'], 'Tahrir defterleri, bölgelerin nüfusunu, vergi kaynaklarını ve dirlik dağılımını kayıt altına alırdı.'),
  ('Devşirme olarak toplanan çocukların önce Türk ailelerinin yanına verilmesinin (Türk\'e verme) amacı hangisidir?', 'Türk dilini ve İslam kültürünü öğrenmelerini sağlamak', ['Tarımda çalışarak vergi ödemelerini sağlamak', 'Ailelerinden kalıcı olarak koparıp köle pazarlarında satmak', 'Tımarlı sipahi olarak yetiştirmek'], 'Türk ailelerin yanında dil, din ve gelenekleri öğrenen gençler sonra Acemi Ocağı\'na alınırdı.'),
  ('Kuşatmalarda düşman surlarının altına tünel kazıp patlayıcı yerleştiren askerî birliğe ne ad verilir?', 'Lağımcılar', ['Humbaracılar', 'Cebeciler', 'Azaplar'], 'Lağımcılar kale surlarının altına lağım açıp barut yerleştirerek gedik açarlardı.'),
  ('Yeniçerilerin padişah değişimlerinde \'cülus bahşişi\' talep etmesi ve bunun verilmemesi hâlinde ayaklanması, hangi sorunun belirtisidir?', 'Ocağın disiplinden uzaklaşıp siyasete karışması', ['Yeniçerilerin sayısının çok azalarak ocağın kapanma noktasına gelmesi', 'Yeniçerilerin savaşmayı bütünüyle bırakması', 'Ocağa yalnız gönüllülerin alınması'], 'Cülus bahşişi geleneği zamanla bir hak gibi görülmeye başlandı; yeniçeriler taleplerini zorla kabul ettirmeye çalışarak siyasete karıştı.'),
  ('Kapıkulu süvarileri ile tımarlı sipahiler arasındaki temel fark hangisidir?', 'Kapıkulu süvarileri maaşlı, tımarlılar dirlik gelirliydi', ['Kapıkulu süvarileri yalnız denizde, tımarlı sipahiler ise karada savaşırdı', 'Tımarlı sipahiler padişahın özel muhafızlarıydı', 'Kapıkulu süvarileri taşrada köylülerden vergi toplardı'], 'Kapıkulu süvarileri (altı bölük halkı) ulufe alan merkez askeriydi; tımarlı sipahiler ise taşrada dirlik gelirine dayanırdı.'),
  ('Osmanlı ordusunda hafif piyade sınıfı olan ve genellikle Anadolu\'daki Türk gençlerinden toplanan, donanmada da görev yapan birlik hangisidir?', 'Azaplar', ['Akıncılar', 'Cebeciler', 'Sekbanlar'], 'Azaplar eyalet askerleri arasında hafif piyadelerdi; savaşlarda ön saflarda ve donanmada görev alırlardı.'),
  ('Osmanlı\'da ilk kez mülkiyet hakkının da tanındığı ve tapu sistemine geçişin hızlandığı kanun hangisidir?', '1858 Arazi Kanunnamesi', ['1840 Ceza Kanunnamesi', '1864 Vilayet Nizamnamesi', '1869 Maarif-i Umumiye Nizamnamesi'], '1858 Arazi Kanunnamesi, toprak düzenini yasal temele oturttu; 1867\'de yabancılara mülk edinme hakkı da tanındı.'),
  ('Vakıf sisteminin Osmanlı toplumunda devletin yükünü hafiflettiği söylenir. Bunun gerekçesi hangisidir?', 'Eğitim, sağlık ve sosyal yardımın vakıflarca karşılanması', ['Vakıfların ordunun tüm maaşlarını ödemesi', 'Vakıfların vergi toplama yetkisine sahip olması', 'Vakıfların ülkenin dış borcunu ve savaş tazminatlarını ödemesi'], 'Okul, hastane, imaret, köprü gibi hizmetler vakıflar aracılığıyla görülerek devlet hazinesinden yapılacak harcamalar azalıyordu.'),
  ('Osmanlı\'da örfi hukuka dayalı bir kanunun şer\'i hukuka uygunluğunun genellikle hangi yolla denetlendiği kabul edilir?', 'Şeyhülislamın fetvası ile', ['Meclis-i Mebusan\'ın oylaması ile', 'Kadıların seçimi ile', 'Valilerin onayı ile'], 'Kanunların ve önemli devlet kararlarının şer\'e uygunluğu şeyhülislamdan alınan fetvalarla denetlenirdi.'),
  ('Kanuni döneminde şeyhülislam olarak görev yapan ve şer\'i hukuk ile örfi hukuku uyumlu hâle getirme çalışmalarıyla tanınan âlim kimdir?', 'Ebussuud Efendi', ['Molla Fenari', 'Zembilli Ali Efendi', 'Kemalpaşazade'], 'Ebussuud Efendi, Kanuni döneminde uzun süre şeyhülislamlık yaptı; kanunnamelerin şer\'e uygunluğunu fetvalarıyla destekledi.'),
  ('Osmanlı\'da bir kadının yokluğunda onun yerine yargı işlerine bakan yardımcısına ne ad verilirdi?', 'Naib', ['Muhtesip', 'Subaşı', 'Müderris'], 'Naib, kadının vekili olarak kaza veya nahiyede yargı görevini yürütürdü.'),
  ('Kadıların merkezden atanması ve yerel güçlerden bağımsız biçimde sancakbeylerinin de yargısal denetimini yapabilmesi neyi sağlamıştır?', 'Taşrada askerî yönetim ile yargı arasında denge', ['Kadıların askerî komutan olmasını', 'Sancakbeylerinin yargıçlık yapmasını', 'Yargının yerel ailelere ve ayanlara babadan oğula bırakılmasını'], 'Askerî yönetici ile kadının ayrı kişiler olması taşrada güçlerin dengelenmesini ve keyfiliğin sınırlanmasını sağlıyordu.'),
  ('Osmanlı\'da devlet görevlilerinin ölümü ya da görevden alınması durumunda mallarına devletçe el konulmasına ne ad verilir?', 'Müsadere', ['Mülazemet', 'Tahrir', 'Tevcih'], 'Müsadere uygulaması, devlet görevlilerinin servetlerine el konulmasıdır; 1839 Tanzimat Fermanı\'yla kaldırılması hedeflendi.'),
  ('İltizam sisteminin köylü üzerindeki olumsuz etkisi en çok hangi nedenden kaynaklanmıştır?', 'Mültezimin kısa sürede kâr elde etmek için ağır vergi toplaması', ['Köylünün toprağını tamamen kaybetmesi', 'Köylünün yeniçeri olmak zorunda kalması', 'Vergilerin hiç toplanmaması'], 'Süreli bir hakka sahip olan mültezim, ödediği parayı ve kârını çıkarmak için köylüyü ezebiliyordu.'),
  ('Abdülmecid döneminde 1840\'ta çıkarılan ilk Osmanlı kâğıt parasının adı nedir?', 'Kaime', ['Esham', 'Akçe', 'Kuruş'], 'Kaime-i mutebere 1840\'ta faizli bir hazine bonosu niteliğinde basıldı; sonradan kâğıt para olarak dolaşıma girdi.'),
  ('Lonca sisteminde \'gedik\' uygulamasının amacı hangisidir?', 'Belirli bir meslekte çalışacak dükkân sayısını sınırlayarak rekabeti denetlemek', ['Esnafa yurt dışına mal satma hakkı vermek', 'Esnafı askerlikten tamamen muaf tutmak', 'Fiyatların serbestçe belirlenmesini sağlamak'], 'Gedik, bir işi yapma ya da dükkân açma hakkıydı; sayısı sınırlı tutularak arz ve rekabet dengelenirdi.'),
  ('Anadolu Selçukluları döneminde kurulup Osmanlı\'nın kuruluş döneminde de etkin olan, esnaf ve sanatkârları dinî-ahlaki ilkelerle örgütleyen teşkilat hangisidir?', 'Ahilik', ['Bektaşilik', 'Loncacılık', 'Fütüvvet'], 'Ahi Evran\'a dayandırılan ahilik, esnafı hem meslek hem ahlak açısından eğitiyordu; zamanla yerini loncalara bıraktı.'),
  ('Osmanlı\'da devlet gelir kaynaklarının (gümrük, maden, tuzla gibi) birimler hâlinde işletilmesine verilen genel ad nedir?', 'Mukataa', ['Malikane', 'Esham', 'Avarız'], 'Mukataa, devlete ait gelir kaynaklarının birim olarak tanımlanması ve emanet ya da iltizam yoluyla işletilmesidir.'),
  ('Coğrafi Keşifler\'den sonra İpek ve Baharat yollarının önemini kaybetmesi Osmanlı\'yı nasıl etkilemiştir?', 'Gümrük gelirlerinin azalmasıyla hazinenin zayıflaması', ['Osmanlı\'nın deniz ticaretinin hızla artması', 'Osmanlı\'nın Amerika\'da sömürge kurması', 'Yeniçerilerin maaşlarının artırılması'], 'Ticaret Atlas Okyanusu\'na kayınca Osmanlı\'dan geçen kervan ticareti azaldı ve gümrük gelirleri düştü.'),
  ('Toprağını geçerli bir neden olmadan terk eden köylüden alınan \'çiftbozan\' vergisinin amacı nedir?', 'Tarımsal üretimin sürekliliğini sağlamak ve köylünün toprağı terk etmesini önlemek', ['Köylünün şehirlere yerleşmesini teşvik etmek', 'Toprakları yabancılara satmayı kolaylaştırmak', 'Tımar sahiplerinin gelirini azaltmak'], 'Çiftbozan resmi, köyden kaçışı caydırarak üretimin ve vergi düzeninin devamını amaçlıyordu.'),
  ('Tımarlı köylünün toprağı kullanma hakkı karşılığında tımar sahibine ödediği temel toprak vergisine ne ad verilir?', 'Çift resmi', ['Cizye', 'Bac-ı pazar', 'Avarız'], 'Çift resmi, Müslüman köylünün işlediği bir çiftlik toprağı için ödediği yıllık vergiydi.'),
  ('Bir Osmanlı köyünde Müslüman bir çiftçinin yıllık buğday ürünü 300 kile ise klasik öşür oranına göre ödemesi beklenen vergi yaklaşık ne kadardır?', '30 kile', ['10 kile', '60 kile', '100 kile'], 'Öşür \'onda bir\' anlamına gelir; 300 kilenin onda biri 30 kiledir.'),
  ('Osmanlı\'da Rum Ortodoks milletinin dinî lideri hangi makamda bulunurdu?', 'Fener Rum Patrikhanesi', ['Bulgar Eksarhlığı', 'Hahambaşılık', 'Kumkapı Ermeni Patrikhanesi'], 'Rum Ortodoksların lideri İstanbul\'daki Fener Rum Patriği idi; Yahudilerin lideri ise Hahambaşı\'ydı.'),
  ('Osmanlı\'nın konar-göçer aşiretleri 17. yüzyıldan itibaren yerleşik hayata geçirmeye çalışmasının (iskân politikası) amacı hangisidir?', 'Vergi toplamayı kolaylaştırmak ve tarımı artırmak', ['Aşiretleri ordudan ve sınır boylarından tamamen uzaklaştırmak', 'Aşiretlerin hayvancılığını yasaklamak', 'Aşiretleri Avrupa\'ya göç ettirmek'], 'Yerleşik hâle getirilen aşiretlerden vergi almak ve onları boş araziyi işlemeye yönlendirmek daha kolaydı; ayrıca asayiş sağlanıyordu.'),
  ('18. yüzyılda taşrada güç kazanan, iltizam ve malikane sayesinde zenginleşen yerel eşraf sınıfına ne ad verilir?', 'Ayan', ['Reaya', 'Yörük', 'Kapıkulu'], 'Ayanlar, taşrada vergi toplama ve asayiş işlerinde güçlenen yerel önderlerdi.'),
  ('1869 Tabiiyet-i Osmaniye Kanunnamesi neyi düzenlemiştir?', 'Osmanlı vatandaşlığını', ['Askerlik süresini', 'Toprak mülkiyetini ve tapuyu', 'Basın özgürlüğünü'], 'Tabiiyet Kanunu, din farkı gözetmeksizin Osmanlı vatandaşlığının hukuki çerçevesini belirledi.'),
  ('Kanuni döneminde Mimar Sinan tarafından yapılan ve tıp eğitimi verilen medreseyi de içeren külliye hangisidir?', 'Süleymaniye Külliyesi', ['Fatih Külliyesi', 'Beyazıt Külliyesi', 'Selimiye Külliyesi'], 'Süleymaniye Külliyesi\'nde tıp medresesi (Darüttıb), darülhadis ve diğer medreseler yer alıyordu.'),
  ('Medreselerde akli bilimlerin (matematik, astronomi, tıp) zamanla geri plana itilmesi hangi sonuca yol açmıştır?', 'Bilimsel düşüncenin gerileyip Batı\'nın izlenememesine', ['Medreselerin tamamen kapanmasına', 'Osmanlı\'da matbaanın erken yayılmasına', 'Medrese mezunlarının toplu hâlde Avrupa üniversitelerinde çalışmaya başlamasına'], 'Akli bilimlerin ihmali, Osmanlı\'nın Avrupa\'daki bilimsel gelişmelerden kopmasında etkili oldu.'),
  ('1773\'te III. Mustafa döneminde açılan ilk Batı tarzı teknik okul hangisidir?', 'Mühendishane-i Bahri Hümayun', ['Mekteb-i Harbiye', 'Mekteb-i Tıbbiye', 'Mekteb-i Mülkiye'], 'Deniz mühendisi yetiştirmek için kurulan bu okul, İstanbul Teknik Üniversitesi\'nin kökeni sayılır.'),
  ('III. Selim döneminde kara ordusuna mühendis yetiştirmek için açılan okul hangisidir?', 'Mühendishane-i Berri Hümayun', ['Mühendishane-i Bahri Hümayun', 'Mekteb-i Harbiye', 'Darülmuallimin'], '1795\'te açılan Mühendishane-i Berri Hümayun kara mühendisi ve topçu subayı yetiştirdi.'),
  ('Osmanlı\'da ilk üniversite girişimi olarak bilinen ve birkaç kez kapanıp açılan kurum hangisidir?', 'Darülfünun', ['Darülmuallimin', 'Darüşşafaka', 'Enderun'], 'Darülfünun 1846\'dan itibaren kurulmaya çalışıldı; 1900\'de Darülfünun-ı Şahane adıyla sürekli hâle geldi; İstanbul Üniversitesi\'nin kökenidir.'),
  ('Öğretmen yetiştirmek amacıyla 1848\'de açılan ilk Osmanlı kurumu hangisidir?', 'Darülmuallimin', ['Darülfünun', 'Mekteb-i Mülkiye', 'Darüşşafaka'], 'Darülmuallimin, rüştiyelere öğretmen yetiştirmek için açılan ilk erkek öğretmen okuludur.'),
  ('1869 Maarif-i Umumiye Nizamnamesi\'nin Osmanlı eğitim sistemine getirdiği yenilik hangisidir?', 'Eğitimi kademelere ayırıp ilköğretimi zorunlu hâle getirmesi', ['Medreseleri tamamen kapatması', 'Yalnız askerî okulları ve harbiyeleri yeniden düzenleyip sayılarını artırması', 'Yabancı okulları yasaklaması'], 'Nizamname eğitimi sıbyan, rüştiye, idadi, sultani ve yükseköğretim gibi kademelere ayırdı ve ilköğretimi zorunlu kıldı.'),
  ('Takiyüddin Rasathanesi\'nin kısa sürede yıktırılması Osmanlı bilim tarihine ilişkin hangi yorumu destekler?', 'Akli bilimlere yönelik çalışmaların siyasi ve dinî çevrelerin tepkisiyle kesintiye uğradığını', ['Osmanlı\'da astronomi çalışmalarının hiç yapılmadığını', 'Rasathanenin yalnız askerî amaçla kurulduğunu', 'Avrupa\'nın rasathaneyi işgal ettiğini'], 'Rasathane, bir kuyruklu yıldız gözlemi ve ardından gelen felaketlerin uğursuzluğa bağlanmasıyla yıktırıldı; bu bilimsel kurumların kırılganlığını gösterir.'),
  ('Semerkant\'tan İstanbul\'a gelerek Fatih döneminde Ayasofya Medresesi\'nde ders veren matematik ve astronomi âlimi kimdir?', 'Ali Kuşçu', ['Takiyüddin', 'Kadızade-i Rumi', 'Molla Lütfi'], 'Uluğ Bey\'in öğrencisi olan Ali Kuşçu, Fatih\'in daveti üzerine İstanbul\'a geldi.'),
  ('IV. Murad döneminde Galata Kulesi\'nden yapma kanatlarla uçarak Üsküdar\'a indiği rivayet edilen kişi kimdir?', 'Hezarfen Ahmed Çelebi', ['Lagari Hasan Çelebi', 'Matrakçı Nasuh', 'Takiyüddin'], 'Evliya Çelebi\'nin aktardığına göre Hezarfen Ahmed Çelebi Galata Kulesi\'nden Üsküdar\'a uçmuştur.'),
  ('Kanuni döneminde sefer güzergâhındaki şehirleri ayrıntılı minyatürlerle resmeden çok yönlü sanatçı kimdir?', 'Matrakçı Nasuh', ['Levni', 'Nakkaş Osman', 'Hezarfen Ahmed Çelebi'], 'Matrakçı Nasuh\'un Beyan-ı Menazil adlı eseri Irakeyn seferindeki şehirleri topografik minyatürlerle gösterir.'),
  ('Lale Devri\'nde minyatür sanatına canlılık ve yeni bir üslup getiren saray nakkaşı kimdir?', 'Levni', ['Matrakçı Nasuh', 'Nakkaş Osman', 'Sinan Bey'], 'Levni, Surname-i Vehbi\'deki minyatürleri ve canlı figürleriyle Lale Devri\'nin ünlü ressamıdır.'),
  ('Âşıkpaşazade ve Neşri gibi 15. yüzyıl tarihçilerinin eserleri Osmanlı tarihi için neden özellikle değerlidir?', 'Kuruluş dönemine ilişkin ilk Osmanlı kaynakları arasında yer almaları', ['Avrupa dillerinde yazılmış olmaları', 'Cumhuriyet döneminde yazılmış olmaları', 'Yalnız matematik konularını içermeleri'], 'Bu eserler Osmanlı\'nın kuruluş dönemini anlatan ilk yerli tarihler arasında olduğundan temel kaynak kabul edilir.'),
  ('Mimar Sinan\'ın \'çıraklık\', \'kalfalık\' ve \'ustalık\' eseri olarak nitelendirdiği yapılardan ustalık eseri hangisidir?', 'Edirne Selimiye Camii', ['İstanbul Süleymaniye Camii', 'İstanbul Şehzade Camii', 'Kayseri Kurşunlu Camii'], 'Sinan; Şehzade Camii\'ni çıraklık, Süleymaniye\'yi kalfalık, Selimiye\'yi ise ustalık eseri olarak değerlendirmiştir.'),
  ('Osmanlı minyatür sanatının Batı resim sanatından ayrılan özelliklerinden biri hangisidir?', 'Derinlik ve perspektif yerine iki boyutlu anlatıma önem vermesi', ['Yalnız yağlı boya kullanması', 'Büyük tuvaller üzerine yapılması', 'Işık-gölge tekniğini ön plana çıkarması'], 'Minyatürler kitap sayfalarında yer alır, perspektif kullanılmaz ve figürler iki boyutlu, anlatımcı biçimde çizilirdi.'),
  ('İznik çiniciliğinin en parlak dönemi olarak kabul edilen ve \'mercan kırmızısı\'nın kullanılmaya başlandığı yüzyıl hangisidir?', '16. yüzyıl', ['14. yüzyıl', '18. yüzyıl', '19. yüzyıl'], 'İznik çiniciliği 16. yüzyılın ikinci yarısında, özellikle Mimar Sinan\'ın yapılarında zirveye ulaştı.'),
  ('Osmanlı\'da güzel yazı sanatına ne ad verilir ve bu alanda \'kıblesi\' olarak anılan sanatçı kimdir?', 'Hat; Şeyh Hamdullah', ['Tezhip; Kara Memi', 'Minyatür; Levni', 'Ebru; Hatip Mehmed Efendi'], 'Şeyh Hamdullah, II. Bayezid döneminde hat sanatında Osmanlı üslubunu oluşturdu ve \'hattatların kıblesi\' olarak anıldı.'),
  ('Osmanlı\'da matbaanın Müslümanlar arasında geç yaygınlaşmasının nedenlerinden biri olarak hangisi gösterilir?', 'Hattatların ve el yazması kitap geleneğinin güçlü olması', ['Osmanlı\'da kâğıt üretiminin hiç bilinmemesi', 'Matbaanın Osmanlı\'da yasa ile hiçbir zaman izin almamış ve hep yasak kalmış olması', 'Osmanlı\'da okuma yazma bilen kimsenin bulunmaması'], 'Güçlü hat ve istinsah geleneği, maliyet ve talep sorunları matbaanın geç yaygınlaşmasında etkili sayılır.'),
  ('Osmanlı topraklarında ilk matbaayı kuran topluluk hangisidir?', 'Yahudiler', ['Rumlar', 'Ermeniler', 'Bulgarlar'], 'İspanya\'dan gelen Yahudiler 1493-94\'te İstanbul\'da ilk matbaayı kurdu; ardından Ermeniler ve Rumlar matbaa açtı.'),
  ('Şinasi\'nin Tercüman-ı Ahval\'in ilk sayısında \'Bir toplumun kendi yararına olan şeyleri söz ya da yazı ile ifade etmesi\' hakkından söz etmesi hangi kavramın savunulduğunu gösterir?', 'Düşünce ve ifade özgürlüğünün', ['Askerlik yükümlülüğünün herkese eşit uygulanmasının', 'Vergide eşitliğin', 'Kuvvetler ayrılığının'], 'Şinasi, halkın kendi çıkarlarını ifade etme hakkını, yani düşünce ve basın özgürlüğünü vurguladı.'),
  ('Şinasi\'nin 1862\'de çıkardığı ve Namık Kemal\'in de yazılarıyla katkıda bulunduğu gazete hangisidir?', 'Tasvir-i Efkâr', ['Ceride-i Havadis', 'İbret', 'Hürriyet'], 'Tasvir-i Efkâr, Yeni Osmanlıların fikirlerini yaydığı önemli gazetelerden biridir.'),
  ('Batıcılık akımının önemli temsilcilerinden olan ve \'İçtihat\' dergisini çıkaran düşünür kimdir?', 'Abdullah Cevdet', ['Ziya Gökalp', 'Mehmed Âkif', 'Said Halim Paşa'], 'Abdullah Cevdet, Batı uygarlığının bütünüyle benimsenmesi gerektiğini İçtihat dergisinde savundu.'),
  ('İsmail Gaspıralı\'nın \'Dilde, fikirde, işte birlik\' sloganıyla savunduğu düşünce hangi akımla ilişkilidir?', 'Türkçülük', ['Osmanlıcılık', 'Batıcılık', 'Liberalizm'], 'Tercüman gazetesini çıkaran Gaspıralı, Türk dünyasında dil ve kültür birliğini savundu.'),
  ('Mehmed Âkif Ersoy\'un yazılarıyla katkı verdiği ve İslamcılık akımının önemli yayın organı olan dergi hangisidir?', 'Sırat-ı Müstakim (Sebilürreşad)', ['İçtihat', 'Türk Yurdu', 'Genç Kalemler (Selanik)'], 'Sırat-ı Müstakim, sonra Sebilürreşad adıyla yayımlanan dergi, İslamcı düşüncenin başlıca yayın organıydı.'),
  ('I. Ahmed döneminde getirilen ve tahtın hanedanın en yaşlı erkek üyesine geçmesini öngören usule ne ad verilir?', 'Ekberiyet', ['Kardeş katli', 'Veliahtlık usulü', 'Kafes usulü'], 'Ekberiyet (en yaşlı erkek üyenin tahta geçmesi) I. Ahmed\'den sonra uygulanmaya başlandı.'),
  ('I. Ahmed\'in kardeşi Mustafa\'yı öldürmemesi ve ekberiyet sistemine geçilmesi hangi uygulamanın yerini almıştır?', 'Taht adayı şehzadelerin öldürülmesi uygulamasının', ['Divan toplantılarının padişah başkanlığında sarayda yapılmasının', 'Devşirmelerin sadrazam olmasının', 'Tımar sisteminin'], 'I. Ahmed kardeşini öldürmedi; ekberiyet ve kafes usulüyle kardeş katli büyük ölçüde sona erdi.'),
  ('Kanuni döneminde 1553 Nahçıvan Seferi sırasında babasının emriyle idam edilen ve askerler arasında çok sevilen şehzade kimdir?', 'Şehzade Mustafa', ['Şehzade Bayezid', 'Şehzade Cihangir', 'Şehzade Selim'], 'Şehzade Mustafa 1553\'te Nahçıvan seferi sırasında Ereğli\'de babasının emriyle boğduruldu.'),
  ('Orhan Bey döneminde Osmanlıların Bizans\'tan aldığı ve Kocaeli yarımadasındaki önemli kale şehri hangisidir?', 'İzmit', ['Trabzon', 'Gelibolu', 'Selanik'], 'İzmit 1337\'de alındı; böylece Kocaeli yarımadası büyük ölçüde Osmanlı\'ya geçti.'),
  ('Rumeli\'ye geçişten sonra fethedilen yerlere tımar dağıtılması ve Anadolu\'dan nüfus getirilmesi birlikte düşünüldüğünde Osmanlı\'nın hangi amacı açıkça görülür?', 'Fethedilen bölgeleri kalıcı yurt hâline getirmek', ['Balkanlar\'dan geçici ganimet toplayıp Anadolu\'ya dönmek', 'Bizans ile toprak paylaşımı yapmak', 'Rumeli\'yi Venedik\'e devretmek'], 'İskân ve tımar birlikte uygulanınca bölgede hem askerî güç hem Türk nüfusu yerleşti; fetih kalıcılaştı.'),
  ('1354\'te bir depremin surlarını yıkması üzerine Süleyman Paşa tarafından alınan ve Rumeli\'deki ilk önemli üs olan şehir hangisidir?', 'Gelibolu', ['Çimpe', 'Edirne', 'Filibe'], 'Gelibolu depremden sonra Süleyman Paşa tarafından alındı ve Rumeli\'ye geçişin ana üssü oldu.'),
  ('Fatih döneminde Osmanlı\'ya katılan ve uzun süre Osmanlı\'nın Anadolu\'daki en güçlü rakibi olan beylik hangisidir?', 'Karamanoğulları', ['Germiyanoğulları', 'Saruhanoğulları', 'Aydınoğulları'], 'Karamanoğulları 1474\'te Fatih döneminde büyük ölçüde Osmanlı\'ya katıldı.'),
  ('Kanuni\'nin 1532 Alman Seferi\'nde Habsburg ordusunun Osmanlı ile meydan savaşına girmemesi neyi göstermektedir?', 'Osmanlı ordusunun Avrupa\'da caydırıcı bir güç olduğunu', ['Habsburgların bu seferden sonra Osmanlı\'ya bağlanıp vergi verdiğini', 'Osmanlı\'nın seferden yenik döndüğünü', 'Fransa\'nın Osmanlı\'ya savaş açtığını'], 'Kanuni ordusu Viyana yakınlarına kadar ilerledi ancak Şarlken savaşa çıkmadı; bu Osmanlı\'nın askerî üstünlüğünü yansıtır.'),
  ('Kanuni\'nin Safevilere karşı yaptığı seferlerin Avrupa\'daki Habsburg-Osmanlı mücadelesine etkisi hangisidir?', 'Doğu cephesi, Osmanlı\'nın Avrupa\'da güç yoğunlaştırmasını zorlaştırmıştır', ['Safevi seferleri Avrupa\'daki savaşları tamamen sona erdirmiştir', 'Safeviler Osmanlı\'yla birlikte Avrupa\'ya sefer yapmıştır', 'Habsburglar Safevilerle savaşmıştır'], 'İki cephede mücadele etmek zorunda kalan Osmanlı, Avrupa\'daki seferlerine ara vermek durumunda kalıyordu; Habsburglar da Safevilerle temas kurmaya çalıştı.'),
  ('Kanuni Sultan Süleyman\'ın uzun süre sadrazamlık yapan ve 1536\'da idam edilen damadı kimdir?', 'Pargalı İbrahim Paşa', ['Rüstem Paşa', 'Sokullu Mehmed Paşa', 'Lütfi Paşa'], 'Pargalı İbrahim Paşa 1523-1536 yılları arasında sadrazamlık yaptı ve 1536\'da idam edildi.'),
  ('16. yüzyılda Osmanlı\'nın ulaştığı coğrafi sınırlar düşünüldüğünde Osmanlı\'nın hangi kıtalarda toprağı bulunuyordu?', 'Avrupa, Asya ve Afrika', ['Yalnız Asya ve Avrupa', 'Avrupa, Asya ve Amerika', 'Yalnız Asya ve Afrika'], 'Balkanlar ve Macaristan (Avrupa), Anadolu ve Orta Doğu (Asya), Mısır ve Kuzey Afrika (Afrika) Osmanlı\'ya bağlıydı.'),
  ('III. Murad döneminde Safevilerle yapılan uzun savaşın ardından imzalanan ve Osmanlı\'nın doğuda en geniş sınırlarına ulaştığı antlaşma hangisidir?', 'Ferhat Paşa Antlaşması', ['Kasr-ı Şirin Antlaşması', 'Amasya Antlaşması', 'Serav Antlaşması'], '1590 Ferhat Paşa (İstanbul) Antlaşması\'yla Tebriz, Azerbaycan ve Kafkasya\'nın büyük kısmı Osmanlı\'ya geçti.'),
  ('1578-1590 Osmanlı-Safevi savaşının Osmanlı ekonomisine olumsuz etkisi ile ilgili hangisi en uygundur?', 'Uzun süren seferlerin hazineye ağır yük getirmesi', ['Osmanlı\'nın İpek Yolu\'nu tamamen kaybetmesi', 'Kapitülasyonların bu savaşla başlaması', 'Osmanlı parasının bu savaşla birlikte altına bağlanıp değer kazanması'], 'Kazanılan toprakların korunması güç oldu; uzun savaşlar hazineyi zorladı ve 1585-86 tağşişine giden mali sıkıntıyı artırdı.'),
  ('1593-1606 yılları arasında Avusturya ile yapılan ve Zitvatorok Antlaşması\'yla sona eren savaşlara ne ad verilir?', 'Uzun Savaşlar', ['Kutsal İttifak Savaşları', 'Otuz Yıl Savaşları', 'Yüzyıl Savaşları'], 'Osmanlı-Habsburg Uzun Savaşları (1593-1606) Haçova zaferi gibi olayları içerir ve Zitvatorok\'la biter.'),
  ('Köprülü Mehmed Paşa\'nın sadarete gelirken \'işlerine kimsenin karışmaması\' şartı koşması, o dönemdeki hangi sorunu yansıtır?', 'Saray çevresinin yönetime müdahalesinin yoğun olmasını', ['Padişahın devlet işlerine hiç ilgi duymayıp yönetimi ulemaya bırakmasını', 'Ulemanın sadrazamı atamasını', 'Yeniçerilerin tamamen dağılmasını'], 'Saray kadınları, ağalar ve çeşitli grupların sürekli müdahalesi, yetki sahibi bir sadrazamı önceden şart koşmaya itti.'),
  ('IV. Mehmed döneminde Venedik\'in Çanakkale Boğazı\'nı abluka altına aldığı ve Köprülü Mehmed Paşa\'nın bu ablukayı kırdığı deniz bölgesi hangisidir?', 'Çanakkale ve Bozcaada-Limni hattı', ['Haliç ve Galata hattı', 'Karadeniz ve Sinop hattı', 'Kızıldeniz ve Cidde ile Yemen kıyıları hattı'], 'Köprülü Mehmed Paşa 1657\'de Çanakkale ablukasını kırdı, Bozcaada ve Limni\'yi geri aldı.'),
  ('Fazıl Mustafa Paşa döneminde gayrimüslimlerden alınan cizyenin gelire göre üç dereceye ayrılarak alınması hangi alandaki bir ıslahat örneğidir?', 'Mali alanda', ['Askerî alanda', 'Eğitim alanında', 'Mimari alanda'], 'Fazıl Mustafa Paşa, cizyeyi kişinin varlık durumuna göre yüksek, orta ve düşük gruplara ayırarak daha adil hâle getirmeye çalıştı.'),
  ('Lale Devri\'nde İstanbul\'un Sadabad gibi mesire yerlerinin, köşk ve bahçelerin yapılması hangi değişimi gösterir?', 'Saray çevresinde yaşam tarzına ve eğlenceye yeni bir anlayış girdiğini', ['Osmanlı\'nın Avrupa\'da yeni ve büyük bir fetih dönemine girdiğini', 'İstanbul nüfusunun azaldığını', 'Osmanlı\'nın Batı\'yla ilişkilerini kestiğini'], 'Kâğıthane\'deki Sadabad gibi yapılar, Fransız saray ve bahçelerinden de esinlenen yeni bir yaşam ve eğlence anlayışını yansıtır.'),
  ('18. yüzyıl başında İstanbul\'da halk arasında uygulanan çiçek aşısı, İngiliz elçinin eşi Lady Montagu tarafından Avrupa\'ya tanıtılmıştır. Bu durum neyi göstermektedir?', 'Bilgi aktarımının her zaman Batı\'dan Doğu\'ya olmadığını', ['Osmanlı\'da tıp bilgisinin hiç bulunmadığını', 'Aşının Avrupa\'dan Osmanlı\'ya getirildiğini', 'Osmanlı\'nın sağlık alanında hiçbir uygulama ve kurum geliştirmediğini'], 'Lady Montagu İstanbul\'da gördüğü çiçek aşısını İngiltere\'ye taşıdı; bu, bilgi akışının iki yönlü olduğunu gösterir.'),
  ('Rus Çarı I. Nikola\'nın Osmanlı Devleti için kullandığı \'hasta adam\' benzetmesi neyi ima eder?', 'Osmanlı\'nın çöküşün eşiğinde olduğunu ve toprakların paylaşılabileceğini', ['Osmanlı\'nın Avrupa\'nın en güçlü devleti olduğunu', 'Osmanlı\'nın Rusya ile ittifak kurmak istediğini', 'Osmanlı\'nın sağlık alanında ve hastane sayısında Avrupa\'dan geri kaldığını'], 'Hasta adam benzetmesi, Osmanlı\'nın yıkılmak üzere olduğu ve mirasının paylaşılması gerektiği düşüncesini yansıtıyordu.'),
  ('1869\'da açılan Süveyş Kanalı\'nın, İngiltere\'nin Mısır\'a ilgisini artırmasının temel nedeni hangisidir?', 'Hindistan\'a giden yolu kısaltan stratejik bir geçit olması', ['Mısır\'ın İngiltere\'den en çok pamuklu kumaş satın alan ülke olması', 'Kanalın Osmanlı donanmasına kapalı tutulması', 'Kanalın Rusya\'nın denetiminde olması'], 'Süveyş Kanalı, İngiltere ile Hindistan arasındaki yolu önemli ölçüde kısalttı; bu nedenle İngiltere bölgeyi denetlemek istedi.'),
  ('1885\'te Bulgaristan\'a katılan, Berlin Antlaşması\'yla özerk bir Osmanlı vilayeti olarak bırakılmış bölge hangisidir?', 'Doğu Rumeli', ['Makedonya', 'Dobruca', 'Batı Trakya'], 'Doğu Rumeli 1885\'te Bulgaristan Prensliği\'ne katıldı.'),
  ('1870\'te Rum Patrikhanesi\'nden ayrılarak Bulgarlara ait ayrı bir kilise kurumu oluşturulmasıyla ortaya çıkan yapı hangisidir?', 'Bulgar Eksarhlığı', ['Bulgar Prensliği', 'Bulgar Hahambaşılığı', 'Bulgar Katolikosluğu'], 'Bulgar Eksarhlığı\'nın kurulması, Bulgar milliyetçiliğinin dinî alanda kurumsallaşmasıdır.'),
  ('Rusya\'nın 1871 Londra Konferansı\'nda Paris Antlaşması\'nın Karadeniz\'le ilgili hükümlerini kaldırtması hangi sonucu doğurmuştur?', 'Rusya\'nın Karadeniz\'de yeniden donanma bulundurabilmesi', ['Osmanlı\'nın Karadeniz kıyılarını tamamen kaybedip kuzeye çekilmesi', 'Boğazların Rusya\'ya devredilmesi', 'Kırım\'ın Osmanlı\'ya geri verilmesi'], 'Fransa\'nın Prusya\'ya yenilmesinden yararlanan Rusya, Karadeniz\'in tarafsızlığını kaldırarak orada yeniden donanma kurma hakkı elde etti.'),
  ('1860\'ta Dürziler ile Maruniler arasındaki çatışmalar sonrasında Avrupa devletlerinin baskısıyla özel bir yönetim statüsü kazanan bölge hangisidir?', 'Lübnan', ['Filistin', 'Yemen', 'Kuveyt'], '1861 Lübnan Nizamnamesi\'yle bölge, Hristiyan bir mutasarrıfın yönetimine verildi.'),
  ('Avrupa\'ya gezi amacıyla giden ilk Osmanlı padişahı olan Sultan Abdülaziz\'in 1867 gezisi hangi vesileyle gerçekleşmiştir?', 'Paris Sergisi\'ni ziyaret etmesi', ['Viyana Kongresi\'ne katılması', 'Berlin Kongresi\'ne katılması', 'Londra Konferansı\'nda bulunması'], 'Abdülaziz 1867 Paris Uluslararası Sergisi\'ne katıldı; ardından Londra ve Viyana\'yı da ziyaret etti.'),
  ('18. yüzyılın sonlarında Yanya\'da neredeyse bağımsız bir yönetim kuran ve II. Mahmud döneminde tasfiye edilen ayan kimdir?', 'Tepedelenli Ali Paşa', ['Alemdar Mustafa Paşa', 'Pazvantoğlu Osman Paşa', 'Kavalalı Mehmed Ali Paşa'], 'Tepedelenli Ali Paşa 1822\'de öldürüldü; isyanı Yunan isyanının başlamasını da kolaylaştırdı.'),
  ('Vidin\'de merkezî otoriteye karşı uzun süre direnen ve III. Selim döneminde sorun yaratan ayan kimdir?', 'Pazvantoğlu Osman Paşa', ['Tepedelenli Ali Paşa', 'Alemdar Mustafa Paşa', 'Cezzar Ahmed Paşa'], 'Pazvantoğlu, Nizam-ı Cedid\'e karşı çıkan ve Vidin\'de fiilen bağımsız hareket eden ayanlardandı.'),
  ('18. yüzyılda Osmanlı\'nın genel dış politika anlayışı en iyi hangi seçenekle açıklanır?', 'Kayıpları geri alıp elde kalanı korumak', ['Avrupa\'nın tamamını fethetmek', 'Afrika\'da yeni sömürgeler kurmak', 'Amerika\'ya açılmak'], 'Karlofça\'dan sonra Osmanlı savunmaya geçti; dış politikanın ana hedefi kayıpları geri almak ve mevcut toprakları korumaktı.'),
  ('III. Selim döneminde Nizam-ı Cedid\'e karşı çıkan çevrelerin Rumeli\'de gerçekleştirdiği ve yeni ordunun Rumeli\'ye yayılmasını engelleyen olay hangisidir?', 'Edirne Vakası', ['Vaka-i Hayriye', 'Patrona Halil İsyanı', '31 Mart Olayı'], '1806 Edirne Vakası\'nda Nizam-ı Cedid birliklerinin Rumeli\'ye yerleştirilmesi yeniçeri ve ayanların direnişiyle durduruldu.'),
  ('III. Selim\'in ıslahatlarının kalıcı olamamasının temel nedeni hangisidir?', 'Eski ocak dururken yeni bir ordu kurulmaya çalışılması', ['Avrupa\'nın ıslahatları desteklemesi', 'Ulemanın ıslahatlara tamamen destek vermesi', 'Hazinede çok fazla para bulunması'], 'Eski kurumlar varlığını sürdürürken kurulan yeni ordu, yeniçeri ve onları destekleyen çevrelerin tepkisine yol açtı.'),
  ('III. Selim\'in ıslahatlarının adının \'Nizam-ı Cedid\' (yeni düzen) olmasının anlamı hangisidir?', 'Yalnız orduyla sınırlı kalmayıp pek çok alanı kapsaması', ['Yalnız donanmada yapılan değişiklikleri ifade etmesi', 'Eski düzenin aynen korunmasını amaçlaması', 'Fransız ordusunun Osmanlı\'ya katılmasını ifade etmesi'], 'Nizam-ı Cedid; askerî, mali, siyasi ve eğitim alanlarındaki yenilikleri kapsayan bir ıslahat programının adıdır.'),
  ('Tanzimat\'ın hemen ardından, 1840\'ta posta işlerini düzenlemek amacıyla kurulan kurum hangisidir?', 'Posta Nezareti', ['Telgraf Nezareti', 'Düyun-u Umumiye', 'Reji İdaresi'], 'Posta Nezareti 1840\'ta kuruldu; telgraf 1855\'te Kırım Savaşı sırasında kullanılmaya başlandı.'),
  ('Aşağıdaki antlaşmalar imzalanma sırasına göre dizildiğinde en sonda hangisi yer alır?', 'Berlin Antlaşması', ['Küçük Kaynarca Antlaşması', 'Karlofça Antlaşması', 'Paris Antlaşması'], 'Karlofça 1699, Küçük Kaynarca 1774, Paris 1856, Berlin 1878\'dir.'),
  ('Aşağıdaki ıslahat hareketlerinden hangisi Lale Devri\'nden sonra ve Tanzimat\'tan önce gerçekleşmiştir?', 'Nizam-ı Cedid ordusunun kurulması', ['Kanun-i Esasi\'nin ilanı', 'Islahat Fermanı\'nın ilanı', 'Düyun-u Umumiye\'nin kurulması'], 'Nizam-ı Cedid 1793 civarında kuruldu; diğerleri Tanzimat\'tan (1839) sonradır.'),
  ('Bursa, Edirne ve İstanbul şehirleri Osmanlı\'ya başkent olma sırasına göre dizildiğinde doğru sıralama hangisidir?', 'Bursa - Edirne - İstanbul', ['Edirne - Bursa - İstanbul - Edirne', 'İstanbul - Bursa - Edirne', 'Bursa - İstanbul - Edirne'], 'Bursa Orhan Bey, Edirne I. Murad, İstanbul ise Fatih döneminde başkent olmuştur.'),
  ('Osmanlı\'da \'serdar\' unvanı hangi kişiye verilirdi?', 'Padişah adına ordu komutanlığı yapan kişiye', ['Divan kâtiplerinin başına', 'Harem\'in yöneticisine', 'Süleymaniye medresesinin baş öğretmenine ve kütüphanesine'], 'Padişahın katılmadığı seferlerde ordunun başındaki kişiye (çoğu zaman sadrazam) serdar-ı ekrem denirdi.'),
  ('Bir tarihçi \'Osmanlı\'nın 16. yüzyıldaki gücü yalnız askerî zaferlere dayanmıyordu.\' görüşünü savunuyor. Aşağıdakilerden hangisi bu görüşü en iyi destekler?', 'Tımar, devşirme ve merkezî bürokrasinin uyum içinde işlemesi', ['Mohaç Savaşı\'nın yaklaşık iki saat gibi kısa bir sürede kazanılması', 'Belgrad\'ın fethedilmesi', 'Preveze\'de Haçlı donanmasının yenilmesi'], 'Diğer seçenekler askerî zaferlerdir; tımar, devşirme ve bürokrasinin işleyişi gücün kurumsal temellerini gösterir.'),
  ('II. Mahmud\'un ıslahatlarının III. Selim\'inkilere göre daha kalıcı olmasının nedeni en iyi hangi seçenekle değerlendirilir?', 'Islahat karşıtı en güçlü odak olan ocağın kaldırılması', ['II. Mahmud\'un hiçbir savaşa girmemesi', 'II. Mahmud\'un ıslahatlarının yalnız eğitimle sınırlı kalması', 'II. Mahmud döneminde Avrupa\'nın Osmanlı\'ya hiç müdahale etmemesi'], 'II. Mahmud, yenilik karşıtı en güçlü odağı ortadan kaldırarak ıslahatların önünü açtı.'),
  ('Osmanlı\'nın 17. yüzyıldaki ıslahatlarıyla 18. yüzyıldaki ıslahatları arasındaki temel farkı en iyi hangisi ifade eder?', '17. yüzyılda eskiye dönüş, 18. yüzyılda Batı\'yı örnek alma hedeflenmiştir', ['17. yüzyılda Batı örnek alınmış, 18. yüzyılda yenilik yapılmamıştır', 'Her iki yüzyılda da yalnız donanma ıslah edilmiştir', 'Her iki yüzyılda da ıslahatlar halkın isteğiyle yapılmıştır'], 'Koçi Bey ve Köprülüler dönemi gelenekselci, Lale Devri ve III. Selim dönemi ise Batı\'yı örnek alan ıslahatları içerir.'),
  ('Osmanlı\'da gayrimüslimlerin din ve ibadet özgürlüğüne sahip olmasının, devletin uzun ömürlü olmasına katkısı en iyi nasıl değerlendirilir?', 'Toplulukların yönetimi benimsemesini kolaylaştırmıştır', ['Gayrimüslimlerin devleti yönetmesini sağlamıştır', 'Devletin gayrimüslimlerden aldığı vergi gelirlerini tamamen ortadan kaldırmıştır', 'Gayrimüslimlerin askerliğe alınmasını zorunlu kılmıştır'], 'Hoşgörülü yönetim farklı inançtaki toplulukların Osmanlı düzeni içinde uzun süre bir arada yaşamasını sağladı.'),
  ('1530 yılında Anadolu\'da yaşayan bir tımarlı sipahinin sefer emri aldığında yapması gereken iş hangisidir?', 'Cebelüleriyle birlikte sancakbeyinin emrinde orduya katılmak', ['İstanbul\'a giderek ulufesini almak', 'Donanmaya kürekçi olarak katılmak', 'Medreseye girerek müderris olmak'], 'Tımarlı sipahiler sefer emri gelince yetiştirdikleri cebelülerle sancakbeyinin bayrağı altında orduya katılırdı.'),
  ('16. yüzyılda bir köylü, tımar sahibinin kendisinden kanunnamede yazandan fazla vergi istediğini düşünüyor. Köylünün başvurabileceği en uygun merci hangisidir?', 'Kazanın kadısı', ['Yeniçeri ağası', 'Kaptan-ı derya', 'Darüssaade ağası'], 'Kadı, kanunnamelere aykırı uygulamalara karşı halkın başvurduğu yargı makamıydı.'),
  ('1850\'li yıllarda yaşayan bir Ermeni tüccar ile Müslüman bir tüccar arasındaki ticari bir anlaşmazlık hangi tür mahkemede görülürdü?', 'Ticaret mahkemesinde', ['Ermeni patrikhanesinin mahkemesinde', 'Yalnız şer\'i mahkemede', 'Konsolosluk mahkemesinde'], 'Tanzimat döneminde farklı dinlerden kişiler arasındaki ticari davalar için karma ticaret mahkemeleri kurulmuştu.'),
  ('Fatih döneminde İstanbul\'a getirilip yerleştirilen bir Rum ailesi, kendi aralarındaki bir miras meselesini nerede çözdürebilirdi?', 'Rum Ortodoks kilisesinin yargı kurumunda', ['Yeniçeri Ocağı\'nda', 'Tersane-i Âmire\'de', 'Enderun Mektebi\'nde'], 'Millet sistemi gereği gayrimüslimler aile ve miras işlerini kendi dinî kurumlarında görebilirdi; isterlerse kadıya da başvurabilirlerdi.'),
  ('Bir araştırmacı, 16. yüzyılda Konya sancağındaki köylerin nüfusunu ve vergi kaynaklarını öğrenmek istiyor. En uygun birincil kaynak hangisidir?', 'Tahrir defterleri', ['Sefaretnameler', 'Takvim-i Vekayi gazetesi', 'Kanun-i Esasi metni'], 'Tahrir defterleri, bölgelerin hane sayısını, vergi kaynaklarını ve dirlikleri kaydeden belgelerdir.'),
  ('Bir tarihçi Osmanlı\'nın 18. yüzyılda Fransa\'ya bakışını incelemek istiyor. Aşağıdaki kaynaklardan hangisi bu konuda en doğrudan bilgi verir?', 'Yirmisekiz Mehmed Çelebi\'nin Sefaretnamesi', ['Âşıkpaşazade Tarihi', 'Kitab-ı Bahriye', 'Koçi Bey Risalesi'], 'Sefaretname, Paris\'e giden elçinin Fransa\'ya dair gözlemlerini içerdiği için en doğrudan kaynaktır.'),
  ('Bir öğrenci, 1876\'da bir mebusun meclisteki konuşmasını, 1878\'de ise meclisin kapatılmasını inceliyor. Bu iki tarih arasında yürürlükte olan yönetim biçimi hangisidir?', 'Meşruti monarşi', ['Mutlak monarşi', 'Cumhuriyet', 'Federal yönetim'], '1876 Kanun-i Esasi ile meşruti monarşiye geçildi; meclis 1878\'de kapatılınca fiilen mutlakiyete dönüldü.'),
  ('Kıyafetinde fes, ceket ve pantolon bulunan bir Osmanlı memurunun fotoğrafının hangi padişahın düzenlemesinden sonraki bir döneme ait olduğu kesindir?', 'II. Mahmud', ['III. Selim', 'III. Ahmed', 'IV. Murad'], 'Fes ve Avrupai kıyafet memurlar için II. Mahmud döneminde zorunlu hâle getirildi.'),
  ('Bir köylünün 1840\'larda devlete ödediği vergiyi doğrudan bir mültezime değil, merkezden atanan bir memura ödemesi hangi düzenlemenin uygulanmaya çalışıldığını gösterir?', 'Tanzimat\'la vergilerin devlet memurlarınca toplanması girişimi', ['Tımar sisteminin yeniden kurulması', 'Malikane sisteminin yaygınlaşması', 'Kapitülasyonların kaldırılması'], 'Tanzimat\'tan sonra iltizam yerine vergileri muhassıl denilen memurlarla toplama denendi, ancak tam başarılı olunamadı.'),
  ('Osmanlı\'da devşirme sisteminin 17. yüzyıldan itibaren terk edilmeye başlanması ile Yeniçeri Ocağı\'na Müslüman Türklerin ve esnafın girmesi birlikte düşünüldüğünde ne sonucuna varılabilir?', 'Ocağın disiplini ve askerî niteliği zayıflamıştır', ['Ocak daha seçkin ve disiplinli hâle gelmiştir', 'Ocağın sayısı azalarak ocak kapanmıştır', 'Ocak yalnız donanmada görev yapmaya başlamıştır'], 'Ocağa farklı yollarla giriş yayılınca eğitim ve disiplin bozuldu; ocak esnaflık yapan, siyasete karışan bir yapıya dönüştü.'),
  ('Ankara Savaşı\'ndan sonra Timur\'un Osmanlı\'nın daha önce ilhak ettiği Anadolu beyliklerini yeniden kurması hangi amaca yönelikti?', 'Anadolu\'da Türk siyasi birliğini bozarak Osmanlı\'yı zayıflatmak', ['Beylikleri Osmanlı\'ya karşı Bizans\'a bağlamak', 'Anadolu\'yu Memlüklere bırakmak', 'Beylikleri Moğol valileriyle yönetmek'], 'Timur, beyliklere topraklarını geri vererek Osmanlı\'nın yeniden güçlenmesini engellemek istedi.'),
  ('II. Bayezid\'in \'Veli\' lakabıyla anılması ve döneminde büyük çaplı fetihlerin azalması onun hangi yönetim anlayışıyla ilişkilendirilir?', 'Barışçı ve imar faaliyetlerine ağırlık veren bir anlayışla', ['Sürekli sefere çıkan bir fetih anlayışıyla', 'Yönetimi tamamen vezirlere bırakan bir anlayışla', 'Batı\'yı örnek alan bir ıslahat anlayışıyla'], 'II. Bayezid dindar kişiliği, imar faaliyetleri ve daha temkinli dış politikasıyla tanınır.'),
  ('Yavuz Sultan Selim\'in babası II. Bayezid\'e karşı mücadele ederek tahta çıkmasında yeniçerilerin desteği önemli rol oynamıştır. Bu durum hangi gelişmenin ilk örneklerinden sayılır?', 'Yeniçerilerin taht değişikliklerinde belirleyici olmaya başlaması', ['Padişahın seçimle belirlenmesi', 'Yeniçeri Ocağı\'nın kaldırılması', 'Divan\'ın padişahı atamaya başlaması'], 'Yeniçerilerin Selim\'i desteklemesi, ocağın siyasi süreçlere müdahalesinin erken örneklerindendir.'),
  ('Osmanlı topraklarında yapılan ilk demiryolu hattı hangisidir?', 'İzmir-Aydın Demiryolu', ['Hicaz Demiryolu', 'Bağdat Demiryolu', 'Haydarpaşa-İzmit Demiryolu'], 'İzmir-Aydın hattı 1856\'da bir İngiliz şirketine verilen imtiyazla yapılmaya başlandı.'),
  ('Çiftçilere düşük faizli kredi vermek amacıyla 1888\'de kurulan banka hangisidir?', 'Ziraat Bankası', ['Osmanlı Bankası', 'İş Bankası', 'Bank-ı Dersaadet'], 'Mithat Paşa\'nın kurduğu Memleket Sandıkları 1888\'de Ziraat Bankası\'na dönüştürüldü.'),
  ('1863\'te kurulan Osmanlı Bankası (Bank-ı Osmani-i Şahane) ile ilgili hangisi doğrudur?', 'Yabancı sermayeyle kurulmuş ve para basma yetkisi verilmiş bir bankaydı', ['Tamamen Osmanlı sermayesiyle kurulan ilk ziraat bankasıydı', 'Yalnız esnafa kredi veren bir loncaydı', 'Yalnız vakıf gelirlerini yöneten bir kurumdu'], 'İngiliz ve Fransız sermayesiyle kurulan banka devlet bankası işlevi gördü ve kâğıt para (banknot) basma yetkisi aldı.'),
  ('Osmanlı\'da kız çocuklarının ortaöğretim görebilmesi için ilk kız rüştiyesi hangi dönemde açılmıştır?', 'Tanzimat dönemi', ['Lale Devri', 'Kuruluş dönemi', 'Köprülüler dönemi'], 'İlk kız rüştiyesi 1858-1859 yıllarında İstanbul\'da açıldı; 1870\'te kız öğretmen okulu (Darülmuallimat) kuruldu.'),
  ('Tanzimat döneminde devlet memurlarına maaş bağlanması, eski uygulamaya göre hangi değişikliği ifade eder?', 'Görevlilerin gelirinin dirlik yerine hazineden düzenli ödemeye dayanması', ['Memurların vergi toplayarak geçinmeye başlaması', 'Memurlukların babadan oğula geçmesi', 'Memurların yalnız askerlerden seçilmesi'], 'Maaş sistemi, devlet hizmetini dirlik ve iltizama bağlı olmaktan çıkararak merkezî bürokrasiyi güçlendirdi.'),
  ('Tanzimat döneminde Avrupa\'daki gibi bir danışma ve kanun hazırlama kurulu olarak 1868\'de kurulan kurum hangisidir?', 'Şura-yı Devlet', ['Meclis-i Mebusan', 'Divan-ı Hümayun', 'Meclis-i Âyan'], 'Şura-yı Devlet (Danıştay\'ın kökeni) 1868\'de kuruldu; Divan-ı Ahkâm-ı Adliye ise yargı alanında faaliyet gösterdi.'),
  ('II. Meşrutiyet döneminde İttihat ve Terakki\'ye muhalefet etmek amacıyla 1911\'de kurulan parti hangisidir?', 'Hürriyet ve İtilaf Fırkası', ['Osmanlı Ahrar Fırkası', 'Terakkiperver Cumhuriyet Fırkası', 'Serbest Cumhuriyet Fırkası'], 'Hürriyet ve İtilaf Fırkası çeşitli muhalif grupları bir araya getirdi; 1912 seçimleri sert bir mücadeleye sahne oldu.'),
  ('1912 seçimlerinin \'Sopalı Seçimler\' olarak anılmasının nedeni hangisidir?', 'Seçimlerde baskı ve şiddet uygulandığı iddiası', ['Seçimlerin yalnız ordu içinde yapılması', 'Seçimlerde kadınların ilk kez oy kullanması', 'Seçimlere hiçbir partinin katılmaması'], 'İttihat ve Terakki\'nin muhaliflere baskı uyguladığı ileri sürüldüğü için bu seçimler \'Sopalı Seçimler\' diye anılır.'),
  ('II. Meşrutiyet döneminde Enver, Talat ve Cemal Paşaların öne çıkması, Osmanlı yönetiminin bu dönemdeki niteliği hakkında neyi gösterir?', 'Yönetimin büyük ölçüde İttihat ve Terakki önderlerinin elinde toplandığını', ['Padişahın yönetimde tek yetkili olduğunu', 'Yönetimin tamamen ulemaya bırakıldığını', 'Yabancı devletlerin Osmanlı\'yı doğrudan yönettiğini'], '1913\'ten sonra yönetim fiilen İttihat ve Terakki\'nin önde gelen isimlerinin denetimine geçti.'),
  ('Osmanlı\'nın I. Dünya Savaşı\'na girmesinde Almanya\'dan Osmanlı\'ya geçen Goeben ve Breslau gemilerinin rolü nedir?', 'Bu gemilerin Karadeniz\'de Rus limanlarını bombalamasıyla Osmanlı\'nın savaşa fiilen girmesi', ['Osmanlı\'nın bu gemilerle İngiltere\'ye saldırması', 'Gemilerin Osmanlı\'yı tarafsız tutması', 'Gemilerin Almanya\'ya geri gönderilmesi'], 'Yavuz ve Midilli adı verilen gemiler Ekim 1914\'te Rus limanlarını bombaladı; Osmanlı böylece savaşa fiilen dahil oldu.'),
  ('I. Dünya Savaşı\'nda Suriye-Filistin Cephesi\'nde Osmanlı\'nın karşısındaki başlıca devlet hangisidir?', 'İngiltere', ['Rusya', 'Fransa', 'İtalya'], 'Suriye-Filistin Cephesi\'nde Osmanlı kuvvetleri esas olarak İngilizlere ve onları destekleyen Arap kuvvetlerine karşı savaştı.'),
  ('16. yüzyılda İstanbul\'da açılmaya başlayan kahvehanelerin toplumsal hayattaki işlevi hangisidir?', 'İnsanların bir araya gelip sohbet ettiği ve haber alışverişi yaptığı mekânlar olması', ['Yalnız askerlerin eğitim gördüğü yerler olması', 'Devletin vergi topladığı resmî daireler olması', 'Medrese öğrencilerinin ders gördüğü yerler olması'], 'Kahvehaneler sohbet, haber ve eğlence mekânı oldu; zaman zaman siyasi konuşmalar nedeniyle yasaklandı.'),
  ('Osmanlı\'da yoksul ve kimsesiz çocukların eğitimi için 1873\'te açılan ve bağışlarla yaşayan okul hangisidir?', 'Darüşşafaka', ['Darülmuallimin', 'Mekteb-i Sanayi', 'Darülfünun'], 'Darüşşafaka Cemiyeti 1863\'te kuruldu; okul 1873\'te açıldı.'),
  ('19. yüzyılda İstanbul\'da \'Altıncı Daire-i Belediye\'nin Galata ve Beyoğlu\'nda kurulması hangi gelişmeyi göstermektedir?', 'Batılı tarzda modern belediyecilik uygulamasının başlamasını', ['Kadılığın İstanbul\'da güçlenmesini', 'İstanbul\'un başkent olmaktan çıkmasını', 'Loncaların belediye işlerini üstlenmesini'], '1857\'de kurulan Altıncı Daire, Avrupa\'daki belediye modellerini örnek alan ilk deneme oldu.'),
];
